# 7. Reconstruct EXACT FNO architecture
# ------------------------------------------------------------
import torch.nn as nn
import torch.nn.functional as F

from models.base_operator import BaseOperator
from models.spectral_kernel import SpectralConv1D


class FNOBaseline(BaseOperator):

    def __init__(self, modes=16, width=64, in_channels=6):
        super().__init__()

        self.modes = modes
        self.width = width

        self.input_projection = nn.Linear(
            in_channels,
            width
        )

        self.conv0 = SpectralConv1D(width, width, modes)
        self.conv1 = SpectralConv1D(width, width, modes)
        self.conv2 = SpectralConv1D(width, width, modes)
        self.conv3 = SpectralConv1D(width, width, modes)

        self.w0 = nn.Conv1d(width, width, 1)
        self.w1 = nn.Conv1d(width, width, 1)
        self.w2 = nn.Conv1d(width, width, 1)
        self.w3 = nn.Conv1d(width, width, 1)

        self.fc1 = nn.Linear(width, 128)
        self.fc2 = nn.Linear(128, 1)

    def forward(
        self,
        state,
        phi,
        flux,
        noise,
        dissipation,
        gamma
    ):

        if gamma.dim() == 1:
            gamma = gamma.unsqueeze(-1)

        x = torch.stack(
            [
                state,
                phi,
                flux,
                noise,
                dissipation,
                gamma.repeat(1, state.shape[-1]),
            ],
            dim=-1,
        )

        # [B, 128, 6]
        x = self.input_projection(x)

        # [B, 64, 128]
        x = x.permute(0, 2, 1)

        x = F.gelu(self.conv0(x) + self.w0(x))
        x = F.gelu(self.conv1(x) + self.w1(x))
        x = F.gelu(self.conv2(x) + self.w2(x))
        x = self.conv3(x) + self.w3(x)

        # [B, 128, 64]
        x = x.permute(0, 2, 1)

        x = F.gelu(self.fc1(x))
        out = self.fc2(x)

        return out.squeeze(-1)


model = FNOBaseline(
    modes=16,
    width=64,
    in_channels=6,
).to(device)

