# ------------------------------------------------------------
# 9. Packed-input forward helper
# ------------------------------------------------------------
def fno_predict(model, inputs):

    state       = inputs[:, 0, :]
    phi         = inputs[:, 1, :]
    flux        = inputs[:, 2, :]
    noise       = inputs[:, 3, :]
    dissipation = inputs[:, 4, :]
    gamma       = inputs[:, 5, 0]

    return model(
        state=state,
        phi=phi,
        flux=flux,
        noise=noise,
        dissipation=dissipation,
        gamma=gamma,
    )

