# ============================================================
# 5. MODEL
# ============================================================

from models.lno_model import LindbladNeuralOperator

model = LindbladNeuralOperator(
    modes=16,
    width=64,
    depth=4,
    in_channels=6
).to(DEVICE)

checkpoint = torch.load(
    CKPT,
    map_location=DEVICE
)

# ------------------------------------------------------------
# Original LNO
# ------------------------------------------------------------

if MODEL_TYPE == "original_lno":

    if (
        "model_state_dict"
        in checkpoint
    ):

        state_dict = checkpoint[
            "model_state_dict"
        ]

    else:

        state_dict = checkpoint

    model.load_state_dict(
        state_dict,
        strict=True
    )

    print(
        "[+] Original LNO loaded."
    )

# ------------------------------------------------------------
# Learnable-alpha LNO
# ------------------------------------------------------------

else:

    # Add the extra alpha parameter BEFORE loading.
    #
    # The exact parameterization used in the pilot:
    #
    #     alpha = softplus(raw_alpha)
    #
    # with four layer-wise values.

    model.raw_dissipative_alpha = torch.nn.Parameter(
        torch.zeros(
            4,
            device=DEVICE,
            dtype=torch.float32
        )
    )

    if (
        "model_state_dict"
        in checkpoint
    ):

        state_dict = checkpoint[
            "model_state_dict"
        ]

    else:

        state_dict = checkpoint

    model.load_state_dict(
        state_dict,
        strict=True
    )

    print(
        "[+] Learnable-dissipation LNO loaded."
    )

# ============================================================
# 6. LEARNABLE-ALPHA FORWARD
# ============================================================

def positive_alpha(model):

    return F.softplus(
        model.raw_dissipative_alpha
    )


def model_forward(inputs):

    state = inputs[:, 0, :]
    phi = inputs[:, 1, :]
    flux = inputs[:, 2, :]
    noise = inputs[:, 3, :]
    dissipation = inputs[:, 4, :]
    gamma = inputs[:, 5, :]

    # --------------------------------------------------------
    # ORIGINAL LNO PATH
    # --------------------------------------------------------

    if MODEL_TYPE == "original_lno":

        output = model(
            state=state,
            phi=phi,
            flux=flux,
            noise=noise,
            dissipation=dissipation,
            gamma=gamma,
        )

        return output

    # --------------------------------------------------------
    # LEARNABLE-DISSIPATION PATH
    # --------------------------------------------------------

    if gamma.dim() == 1:

        gamma = gamma.unsqueeze(-1)

    x = torch.stack(
        [
            state,
            phi,
            flux,
            noise,
            dissipation,
            gamma.repeat(
                1,
                state.shape[-1]
            ),
        ],
        dim=-1
    )

    x = model.input_projection(
        x
    )

    x = x.permute(
        0,
        2,
        1
    )

    alphas = positive_alpha(
        model
    )

    spectral_energy_history = []

    for k in range(
        model.depth
    ):

        spectral_update = (
            model
            .spectral_layers[k](x)
        )

        pointwise_update = (
            model
            .pointwise_layers[k](x)
        )

        x_linear = (
            spectral_update
            + pointwise_update
        )

        layer = (
            model
            .dissipative_layers[k]
        )

        # ----------------------------------------------------
        # Lindblad dissipator
        # ----------------------------------------------------

        L = layer.jump_transform

        xp = x_linear.permute(
            0,
            2,
            1
        )

        LTL = (
            L.t()
            @ L
        )

        D = (
            (xp @ L.t()) @ L
            - 0.5 * (
                xp @ LTL
                + xp @ LTL.t()
            )
        )

        D = D.permute(
            0,
            2,
            1
        )

        D = (
            gamma.view(
                -1,
                1,
                1
            )
            * D
        )

        # ----------------------------------------------------
        # Coherent
        # ----------------------------------------------------

        padded = F.pad(
            x_linear,
            (2, 2),
            mode="circular"
        )

        coherent = F.conv1d(
            padded,
            layer.coherent_kernel
        )

        # ----------------------------------------------------
        # Spatial diffusion
        # ----------------------------------------------------

        left = torch.roll(
            x_linear,
            -1,
            dims=-1
        )

        right = torch.roll(
            x_linear,
            1,
            dims=-1
        )

        spatial = (
            layer.spatial_diffusion_weight
            * (
                left
                - 2.0 * x_linear
                + right
            )
        )

        # ----------------------------------------------------
        # Learnable dissipative coupling
        # ----------------------------------------------------

        x = (
            x_linear
            + coherent
            + alphas[k] * D
            + spatial
        )

        if k < model.depth - 1:

            x = F.gelu(
                x
            )

        # spectral diagnostic
        try:

            spectral_energy_history.append(
                model.compute_spectral_energy(x)
            )

        except Exception:

            pass

    instability_map = (
        model
        .instability_head(x)
    )

    x_out = x.permute(
        0,
        2,
        1
    )

    predicted = (
        model
        .output_projection(
            x_out
        )
        .squeeze(-1)
    )

    return {
        "next_state":
            predicted,

        "instability_map":
            instability_map.squeeze(1),

        "spectral_energy":
            spectral_energy_history,
    }


# ============================================================
# 7. MODEL INTEGRITY
# ============================================================

model.eval()

parameter_count = sum(
    p.numel()
    for p in model.parameters()
)

print(
    "\n[+] Parameter count:",
    f"{parameter_count:,}"
)

with torch.no_grad():

    first_inputs, first_targets = next(
        iter(test_loader)
    )

    first_inputs = first_inputs.float().to(
        DEVICE
    )

    first_targets = first_targets.float().to(
        DEVICE
    )

    first_output = model_forward(
        first_inputs
    )

    first_prediction = first_output[
        "next_state"
    ]

assert first_prediction.shape == (
    32,
    128
)

assert torch.isfinite(
    first_prediction
).all()

print(
    "[+] Forward check: PASSED"
)

print(
    "[+] Input geometry:",
    tuple(first_inputs.shape)
)

print(
    "[+] Output geometry:",
    tuple(first_prediction.shape)
)

# ============================================================
# 8. COMPLETE TEST-SET EVALUATION
# ============================================================

print("\n" + "=" * 90)
print("RUNNING COMPLETE 3000-SAMPLE TEST SET")
print("=" * 90)

all_predictions = []
all_targets = []
all_inputs = []

all_instability = []

start_time = time.time()

with torch.no_grad():

    for batch_idx, (
        inputs,
        targets
    ) in enumerate(
        test_loader,
        start=1
    ):

        inputs = inputs.float().to(
            DEVICE
        )

        targets = targets.float().to(
            DEVICE
        )

        output = model_forward(
            inputs
        )

        predictions = output[
            "next_state"
        ]

        all_predictions.append(
            predictions.cpu()
        )

        all_targets.append(
            targets.cpu()
        )

        all_inputs.append(
            inputs.cpu()
        )

        if (
            "instability_map"
            in output
        ):

            all_instability.append(
                output[
                    "instability_map"
                ].cpu()
            )

        if (
            batch_idx == 1
            or batch_idx % 25 == 0
            or batch_idx == len(test_loader)
        ):

            print(
                f"    Batch "
                f"{batch_idx:03d}/"
                f"{len(test_loader)}"
            )

predictions = torch.cat(
    all_predictions,
    dim=0
)

targets = torch.cat(
    all_targets,
    dim=0
)

inputs_all = torch.cat(
    all_inputs,
    dim=0
)

elapsed = (
    time.time()
    - start_time
)

print(
    "\n[+] Prediction tensor:",
    tuple(predictions.shape)
)

print(
    "[+] Target tensor:",
    tuple(targets.shape)
)

print(
    "[+] Input tensor:",
    tuple(inputs_all.shape)
)

assert predictions.shape == (
    3000,
    128
)

assert targets.shape == (
    3000,
    128
)

# ============================================================
# 9. CORE METRICS
# ============================================================

error = (
    predictions
    - targets
)

# RMSE
mse = torch.mean(
    error ** 2
).item()

rmse = (
    mse ** 0.5
)

# MAE
mae = torch.mean(
    torch.abs(error)
).item()

# Relative L2
relative_l2 = (
    torch.linalg.vector_norm(
        error
    )
    /
    (
        torch.linalg.vector_norm(
            targets
        )
        + 1e-30
    )
).item()

# ============================================================
# 10. PHYSICAL / STRUCTURAL METRICS
# ============================================================

# Mass error:
# mean absolute difference of spatial integral/sum
pred_mass = predictions.sum(
    dim=-1
)

true_mass = targets.sum(
    dim=-1
)

mass_error = torch.mean(
    torch.abs(
        pred_mass
        - true_mass
    )
).item()

# ------------------------------------------------------------
# Entropy error
# ------------------------------------------------------------

eps = 1e-12

pred_prob = (
    torch.softmax(
        predictions,
        dim=-1
    )
    + eps
)

true_prob = (
    torch.softmax(
        targets,
        dim=-1
    )
    + eps
)

pred_entropy = -torch.sum(
    pred_prob
    * torch.log(pred_prob),
    dim=-1
)

true_entropy = -torch.sum(
    true_prob
    * torch.log(true_prob),
    dim=-1
)

entropy_error = torch.mean(
    torch.abs(
        pred_entropy
        - true_entropy
    )
).item()

# ------------------------------------------------------------
# Instability index
# ------------------------------------------------------------

max_abs_state = torch.max(
    torch.abs(
        predictions
    )
).item()

instability_index = max_abs_state

# ------------------------------------------------------------
# Dissipation rate
# ------------------------------------------------------------

# Current observable proxy:
# normalized one-step change magnitude.

input_state = inputs_all[:, 0, :]

dissipation_rate = torch.mean(
    torch.abs(
        predictions
        - input_state
    )
).item()

# ------------------------------------------------------------
# Spectral energy
# ------------------------------------------------------------

pred_fft = torch.fft.rfft(
    predictions,
    dim=-1
)

spectral_energy = torch.mean(
    torch.abs(
        pred_fft
    ) ** 2
).item()

# ============================================================
# 11. PRINT FINAL RESULTS
# ============================================================

print("\n" + "=" * 90)
print(
    f"{MODEL_TYPE.upper()} — FINAL TEST RESULTS"
)
print("=" * 90)

print(
    f"RMSE              : {rmse:.10e}"
)

print(
    f"Relative_L2       : {relative_l2:.10e}"
)

print(
    f"MAE               : {mae:.10e}"
)

print(
    f"Mass_Error        : {mass_error:.10e}"
)

print(
    f"Entropy_Error     : {entropy_error:.10e}"
)

print(
    f"Instability_Index : {instability_index:.10e}"
)

print(
    f"Dissipation_Rate  : {dissipation_rate:.10e}"
)

print(
    f"Spectral_Energy   : {spectral_energy:.10e}"
)

print("=" * 90)

# ============================================================
