# ============================================================
# 3. SHA256
# ============================================================

def sha256_file(path):

    h = hashlib.sha256()

    with open(
        path,
        "rb"
    ) as f:

        for chunk in iter(
            lambda: f.read(1024 * 1024),
            b""
        ):

            h.update(chunk)

    return h.hexdigest()


fno_sha = sha256_file(
    FNO_CKPT
)

lno_sha = sha256_file(
    LNO_CKPT
)

print(
    "\n[+] FNO SHA256:",
    fno_sha
)

