# ============================================================
# 7. FNO FORWARD
# ============================================================

def fno_forward(
    inputs
):

    # FNO baseline accepts packed
    # [B, 6, 128] according to the
    # verified test geometry.

    output = fno(
        inputs
    )

    if isinstance(
        output,
        dict
    ):

        if "next_state" in output:

            output = output[
                "next_state"
            ]

        elif "prediction" in output:

            output = output[
                "prediction"
            ]

        else:

            raise KeyError(
                "Unknown FNO output keys: "
                + str(
                    output.keys()
                )
            )

    if output.ndim == 3:

        if output.shape[-1] == 1:

            output = output.squeeze(-1)

        elif output.shape[1] == 1:

            output = output.squeeze(1)

    return output

# ============================================================
# 8. LNO FORWARD
# ============================================================

def lno_forward(
    inputs
):

    state = inputs[:, 0, :]
    phi = inputs[:, 1, :]
    flux = inputs[:, 2, :]
    noise = inputs[:, 3, :]
    dissipation = inputs[:, 4, :]
    gamma = inputs[:, 5, :]

    # --------------------------------------------------------
    # Original LNO
    # --------------------------------------------------------

    if not USE_PILOT:

        output = lno(
            state=state,
            phi=phi,
            flux=flux,
            noise=noise,
            dissipation=dissipation,
            gamma=gamma,
        )

        if "next_state" in output:

            return output[
                "next_state"
            ]

        if "prediction" in output:

            return output[
                "prediction"
            ]

        raise KeyError(
            "Unknown LNO output keys."
        )

    # --------------------------------------------------------
    # Learnable-alpha LNO
    # --------------------------------------------------------

    if gamma.dim() == 1:

        gamma = gamma.unsqueeze(
            -1
        )

    x = torch.stack(
        [
            state,
            phi,
            flux,
            noise,
            dissipation,
            gamma.repeat(
                1,
                state.shape[-1]
            ),
        ],
        dim=-1
    )

    x = lno.input_projection(
        x
    )

    x = x.permute(
        0,
        2,
        1
    )

    alphas = F.softplus(
        lno.raw_dissipative_alpha
    )

    for k in range(
        lno.depth
    ):

        spectral_update = (
            lno.spectral_layers[k](x)
        )

        pointwise_update = (
            lno.pointwise_layers[k](x)
        )

        x_linear = (
            spectral_update
            + pointwise_update
        )

        layer = (
            lno.dissipative_layers[k]
        )

        L = layer.jump_transform

        xp = x_linear.permute(
            0,
            2,
            1
        )

        LTL = (
            L.t()
            @ L
        )

        D = (
            (xp @ L.t()) @ L
            - 0.5 * (
                xp @ LTL
                + xp @ LTL.t()
            )
        )

        D = D.permute(
            0,
            2,
            1
        )

        D = (
            gamma
            .view(
                -1,
                1,
                1
            )
            * D
        )

        padded = F.pad(
            x_linear,
            (2, 2),
            mode="circular"
        )

        coherent = F.conv1d(
            padded,
            layer.coherent_kernel
        )

        left = torch.roll(
            x_linear,
            -1,
            dims=-1
        )

        right = torch.roll(
            x_linear,
            1,
            dims=-1
        )

        spatial = (
            layer.spatial_diffusion_weight
            * (
                left
                - 2.0 * x_linear
                + right
            )
        )

        x = (
            x_linear
            + coherent
            + alphas[k] * D
            + spatial
        )

        if k < lno.depth - 1:

            x = F.gelu(
                x
            )

    prediction = (
        lno.output_projection(
            x.permute(
                0,
                2,
                1
            )
        )
        .squeeze(-1)
    )

    return prediction

