print(
    "BEGIN FINAL OOD SWEEP"
)

print(
    "=" * 90
)

rows = []

for sigma in SIGMA_VALUES:

    # Reinitialize deterministic RNG for
    # each sigma so FNO and LNO receive
    # EXACTLY the same perturbations.

    generator = torch.Generator(
        device="cpu"
    )

    generator.manual_seed(
        SEED
        +
        int(
            round(
                sigma * 1000
            )
        )
    )

    fno_sq_error = 0.0
    lno_sq_error = 0.0

    fno_abs_error = 0.0
    lno_abs_error = 0.0

    total_elements = 0

    print(
        f"\n--- sigma={sigma:.2f} ---"
    )

    for batch_idx, (
        clean_inputs,
        targets
    ) in enumerate(
        test_loader,
        start=1
    ):

        clean_inputs = (
            clean_inputs
            .float()
        )

        targets = (
            targets
            .float()
            .to(DEVICE)
        )

        # ----------------------------------------------------
        # Same perturbation for both models
        # ----------------------------------------------------

        noise = torch.randn(
            clean_inputs.shape,
            generator=generator,
            dtype=clean_inputs.dtype
        )

        perturbed_inputs = (
            clean_inputs
            + sigma * noise
        )

        perturbed_inputs = (
            perturbed_inputs
            .to(DEVICE)
        )

        # ----------------------------------------------------
        # FNO
        # ----------------------------------------------------

        with torch.no_grad():

            fno_pred = fno_forward(
                perturbed_inputs
            )

            # ------------------------------------------------
            # LNO
            # ------------------------------------------------

            lno_pred = lno_forward(
                perturbed_inputs
            )

        # ----------------------------------------------------
        # Finite
        # ----------------------------------------------------

        if not torch.isfinite(
            fno_pred
        ).all():

            raise RuntimeError(
                f"Non-finite FNO output at "
                f"sigma={sigma}, "
                f"batch={batch_idx}"
            )

        if not torch.isfinite(
            lno_pred
        ).all():

            raise RuntimeError(
                f"Non-finite LNO output at "
                f"sigma={sigma}, "
                f"batch={batch_idx}"
            )

        # ----------------------------------------------------
        # Errors
        # ----------------------------------------------------

        fno_error = (
            fno_pred
            - targets
        )

        lno_error = (
            lno_pred
            - targets
        )

        fno_sq_error += (
            torch.sum(
                fno_error
                ** 2
            ).item()
        )

        lno_sq_error += (
            torch.sum(
                lno_error
                ** 2
            ).item()
        )

        fno_abs_error += (
            torch.sum(
                torch.abs(
                    fno_error
                )
            ).item()
        )

        lno_abs_error += (
            torch.sum(
                torch.abs(
                    lno_error
                )
            ).item()
        )

        total_elements += (
            fno_error.numel()
        )

    # --------------------------------------------------------
    # Global metrics
    # --------------------------------------------------------

    fno_mse = (
        fno_sq_error
        /
        total_elements
    )

    lno_mse = (
        lno_sq_error
        /
        total_elements
    )

    fno_rmse = (
        fno_mse
        ** 0.5
    )

    lno_rmse = (
        lno_mse
        ** 0.5
    )

    fno_mae = (
        fno_abs_error
        /
        total_elements
    )

    lno_mae = (
        lno_abs_error
        /
        total_elements
    )

    # --------------------------------------------------------
    # Improvement
    #
    # Positive = LNO better
    # --------------------------------------------------------

    lno_improvement = (
        (
            fno_rmse
            - lno_rmse
        )
        /
        (
            fno_rmse
            + 1e-30
        )
        * 100.0
    )

    winner = (
        "LNO"
        if lno_rmse < fno_rmse
        else
        "FNO"
        if fno_rmse < lno_rmse
        else
        "Tie"
    )

    rows.append({

        "sigma":
            sigma,

        "FNO_RMSE":
            fno_rmse,

        "LNO_RMSE":
            lno_rmse,

        "FNO_MAE":
            fno_mae,

        "LNO_MAE":
            lno_mae,

        "LNO_improvement_percent":
            lno_improvement,

        "Winner":
            winner,

        "FNO_finite":
            True,

        "LNO_finite":
            True,
    })

    print(
        f"sigma={sigma:>4.2f} | "
        f"FNO RMSE={fno_rmse:.10e} | "
        f"LNO RMSE={lno_rmse:.10e} | "
        f"LNO improvement={lno_improvement:+.4f}% | "
        f"Winner={winner}"
    )

