# ============================================================
# 9. SHA256 OF ZIP
# ============================================================

def sha256_file(
    path
):

    h = hashlib.sha256()

    with open(
        path,
        "rb"
    ) as f:

        for chunk in iter(
            lambda:
                f.read(
                    1024 * 1024
                ),
            b""
        ):

            h.update(
                chunk
            )

    return h.hexdigest()


zip_sha256 = sha256_file(
    ZIP_PATH
)

