def save_figure(
    fig,
    filename
):

    base = (
        FIG_DIR
        / filename
    )

    fig.savefig(
        str(base) + ".png",
        dpi=DPI,
        bbox_inches="tight",
        pad_inches=0.03
    )

    fig.savefig(
        str(base) + ".pdf",
        bbox_inches="tight",
        pad_inches=0.03
    )

    fig.savefig(
        str(base) + ".svg",
        bbox_inches="tight",
        pad_inches=0.03
    )

    plt.close(fig)

    print(
        "[FIGURE]",
        filename
    )


def read_csv(
    path,
    label
):

    path = Path(path)

    if not path.is_file():

        print(
            f"[MISSING] {label}: {path}"
        )

        return None

    df = pd.read_csv(
        path
    )

    print(
        f"[LOADED] {label}: {path}"
    )

    return df


def read_json(
    path,
    label
):

    path = Path(path)

    if not path.is_file():

        print(
            f"[MISSING] {label}: {path}"
        )

        return None

    with open(
        path,
        "r"
    ) as f:

        obj = json.load(
            f
        )

    print(
        f"[LOADED] {label}: {path}"
    )

    return obj


def latex_escape(
    text
):

    text = str(text)

    replacements = {

        "&": r"\&",
        "%": r"\%",
        "_": r"\_",
        "#": r"\#",
        "$": r"\$",
    }

    for old, new in replacements.items():

        text = text.replace(
            old,
            new
        )

    return text


