# ============================================================
# STEP: STEP_05
# HEADING: # STEP 5 — PROPER LNO PHYSICAL REPRESENTATION
# ORIGINAL CELL: 33
# ============================================================

# ============================================================
# STEP 5 — PROPER LNO PHYSICAL REPRESENTATION
#            + LINDBLAD-CONSTRAINED KERNEL PROTOTYPE
#
# PURPOSE:
#   Test whether the candidate information-state
#
#       R = z z^T / Tr(z z^T)
#
#   can support a stable, differentiable Lindblad-form
#   dynamical kernel.
#
# TESTS:
#   1. Information preservation
#   2. Lindblad dissipative compatibility
#   3. Trace preservation
#   4. Symmetry / PSD preservation
#   5. Environmental response
#   6. Repeated-step stability
#   7. Non-vanishing gradients
#
# NO TRAINING OF FULL LNO
# NO DATASET MODIFICATION
# NO CHECKPOINT MODIFICATION
# ============================================================

import os
import json
import math
import numpy as np
import pandas as pd
import torch
import torch.nn as nn
import torch.nn.functional as F

from pathlib import Path

# scipy is used only for a tiny 36x36 prototype matrix exponential
from scipy.linalg import expm

# ============================================================
# 1. ROOT
# ============================================================

ROOT = Path(
    "/content/"
    "Lindblad-Neural-Operators-for-Inverse-Dynamical-Imaging-of-Stochastic-Poisson-Ne"
)

os.chdir(ROOT)

print("=" * 100)
print("STEP 5 — LINDBLAD-CONSTRAINED KERNEL PROTOTYPE")
print("=" * 100)

# ============================================================
# 2. DEVICE
# ============================================================

device = torch.device(
    "cuda"
    if torch.cuda.is_available()
    else "cpu"
)

print(
    "[+] Device:",
    device
)

# ============================================================
# 3. LOAD ONE VERIFIED PAIRED TRAJECTORY
# ============================================================

PAIR_DIR = (
    ROOT
    / "results"
    / "step3_paired_trajectories"
)

# Use stochastic regime as main controlled prototype
PAIR_PATH = (
    PAIR_DIR
    / "stochastic_paired.npz"
)

assert PAIR_PATH.is_file(), (
    f"Missing paired trajectory:\n{PAIR_PATH}"
)

data = np.load(
    PAIR_PATH
)

print(
    "[+] Source:",
    PAIR_PATH
)

# ------------------------------------------------------------
# Load required arrays
# ------------------------------------------------------------

R_open = data[
    "R_open"
].astype(
    np.float64
)

R_ref = data[
    "R_reference"
].astype(
    np.float64
)

open_state = data[
    "open_state"
].astype(
    np.float64
)

ref_state = data[
    "reference_state"
].astype(
    np.float64
)

open_phi = data[
    "open_phi"
].astype(
    np.float64
)

open_flux = data[
    "open_flux"
].astype(
    np.float64
)

open_noise = data[
    "open_noise"
].astype(
    np.float64
)

open_diss = data[
    "open_dissipation"
].astype(
    np.float64
)

open_inst = data[
    "open_instability"
].astype(
    np.float64
)

open_gamma = data[
    "open_gamma"
].astype(
    np.float64
)

# ============================================================
# 4. SHAPE CHECKS
# ============================================================

T, NX, DIM, DIM2 = (
    R_open.shape
)

assert DIM == 6
assert DIM2 == 6

print(
    "[+] R_open:",
    R_open.shape
)

print(
    "[+] R_reference:",
    R_ref.shape
)

print(
    "[+] Spatial points:",
    NX
)

