# ============================================================
# 8. STRUCTURE TEST
# ============================================================

def matrix_structure_test(
    R,
    label
):

    trace = np.trace(
        R,
        axis1=-2,
        axis2=-1
    )

    trace_error = float(
        np.max(
            np.abs(
                trace
                -
                1.0
            )
        )
    )

    symmetry_error = float(
        np.max(
            np.abs(
                R
                -
                np.swapaxes(
                    R,
                    -1,
                    -2
                )
            )
        )
    )

    subset = R[
        :min(
            T,
            32
        ),
        ::max(
            1,
            NX // 16
        )
    ]

    eigvals = np.linalg.eigvalsh(
        subset
    )

    min_eig = float(
        np.min(
            eigvals
        )
    )

    print(
        "\n" + "-" * 80
    )

    print(
        label
    )

    print(
        "-" * 80
    )

    print(
        "Trace max error:",
        f"{trace_error:.12e}"
    )

    print(
        "Symmetry max error:",
        f"{symmetry_error:.12e}"
    )

    print(
        "Minimum eigenvalue:",
        f"{min_eig:.12e}"
    )

    return (
        trace_error,
        symmetry_error,
        min_eig
    )


(
    Ropen_trace_error,
    Ropen_symmetry_error,
    Ropen_min_eig,
) = matrix_structure_test(
    R_open,
    "OPEN INFORMATION MATRIX"
)

(
    Rref_trace_error,
    Rref_symmetry_error,
    Rref_min_eig,
) = matrix_structure_test(
    R_reference,
    "REFERENCE INFORMATION MATRIX"
)

