# ============================================================
# 18. NATIVE PYTHON SCALAR CONVERSION
#
# This fixes the json.dump bool / NumPy scalar error.
# ============================================================

def native_scalar(
    value
):

    if isinstance(
        value,
        (
            np.bool_,
        )
    ):

        return bool(
            value
        )

    if isinstance(
        value,
        (
            np.integer,
        )
    ):

        return int(
            value
        )

    if isinstance(
        value,
        (
            np.floating,
        )
    ):

        return float(
            value
        )

    if isinstance(
        value,
        (
            bool,
            int,
            float,
            str,
        )
    ):

        return value

    return value


