# ============================================================
# 11. SPECTRAL CONVOLUTION
# ============================================================

class SpectralConv1D(
    nn.Module
):

    def __init__(
        self,
        in_channels,
        out_channels,
        modes,
    ):

        super().__init__()

        self.in_channels = in_channels
        self.out_channels = out_channels
        self.modes = modes

        scale = 1.0 / math.sqrt(
            in_channels
            *
            out_channels
        )

        self.weight_real = nn.Parameter(
            scale
            *
            torch.randn(
                in_channels,
                out_channels,
                modes
            )
        )

        self.weight_imag = nn.Parameter(
            scale
            *
            torch.randn(
                in_channels,
                out_channels,
                modes
            )
        )

    def forward(
        self,
        x
    ):

        B, C, NX_local = x.shape

        x_ft = torch.fft.rfft(
            x,
            dim=-1
        )

        n_modes = min(
            self.modes,
            x_ft.shape[-1]
        )

        out_ft = torch.zeros(
            B,
            self.out_channels,
            x_ft.shape[-1],
            dtype=torch.complex64,
            device=x.device
        )

        weight = torch.complex(
            self.weight_real[
                :,
                :,
                :n_modes
            ],
            self.weight_imag[
                :,
                :,
                :n_modes
            ]
        )

        out_ft[
            ...,
            :n_modes
        ] = torch.einsum(
            "bim,iom->bom",
            x_ft[
                ...,
                :n_modes
            ],
            weight
        )

        return torch.fft.irfft(
            out_ft,
            n=NX_local,
            dim=-1
        )

# ============================================================
# 12. FNO BASELINE
# ============================================================

class FNOBaseline(
    nn.Module
):

    """
    Fair unconstrained Fourier neural operator baseline.

    INPUT:
        R          = 36 channels
        amplitude  = 1 channel
        gamma      = 1 channel
        sigma      = 1 channel

    TOTAL:
        39 channels

    OUTPUT:
        R_next
        amplitude_next

    IMPORTANT:
        No Lindblad block.
        No dissipative constraint.
        No physics-specific stabilization.

    This is the control baseline against which LNO will be
    compared.
    """

    def __init__(
        self,
        dim=6,
        width=64,
        modes=16,
        depth=4,
    ):

        super().__init__()

        self.dim = dim
        self.width = width
        self.modes = modes
        self.depth = depth

        input_channels = (
            dim * dim
            + 3
        )

        self.input_projection = nn.Conv1d(
            input_channels,
            width,
            kernel_size=1
        )

        self.spectral_layers = nn.ModuleList(
            [
                SpectralConv1D(
                    width,
                    width,
                    modes
                )
                for _ in range(
                    depth
                )
            ]
        )

        self.pointwise_layers = nn.ModuleList(
            [
                nn.Conv1d(
                    width,
                    width,
                    kernel_size=1
                )
                for _ in range(
                    depth
                )
            ]
        )

        self.R_head = nn.Conv1d(
            width,
            dim * dim,
            kernel_size=1
        )

        self.A_head = nn.Conv1d(
            width,
            1,
            kernel_size=1
        )

    def forward(
        self,
        R,
        amplitude,
        gamma,
        sigma,
    ):

        B, NX_local, D, D2 = (
            R.shape
        )

        assert D == self.dim
        assert D2 == self.dim

        # ----------------------------------------------------
        # Flatten R
        # ----------------------------------------------------

        R_flat = R.reshape(
            B,
            NX_local,
            D * D
        )

        # ----------------------------------------------------
        # Environment-conditioned channels
        # ----------------------------------------------------

        assert amplitude.shape == (
            B,
            NX_local
        )

        assert gamma.shape == (
            B,
            NX_local
        )

        assert sigma.shape == (
            B,
            NX_local
        )

        env = torch.stack(
            [
                amplitude,
                gamma,
                sigma,
            ],
            dim=-1
        )

        inp = torch.cat(
            [
                R_flat,
                env,
            ],
            dim=-1
        )

        x = inp.permute(
            0,
            2,
            1
        )

        x = self.input_projection(
            x
        )

        # ----------------------------------------------------
        # Fourier layers
        # ----------------------------------------------------

        for k in range(
            self.depth
        ):

            spectral = (
                self.spectral_layers[k](
                    x
                )
            )

            pointwise = (
                self.pointwise_layers[k](
                    x
                )
            )

            x = (
                spectral
                +
                pointwise
            )

            if k < (
                self.depth - 1
            ):

                x = F.gelu(
                    x
                )

        # ----------------------------------------------------
        # R output
        # ----------------------------------------------------

        R_next = self.R_head(
            x
        )

        R_next = (
            R_next
            .permute(
                0,
                2,
                1
            )
            .reshape(
                B,
                NX_local,
                D,
                D
            )
        )

        # Keep symmetry only for a clean common output format.
        # This is NOT a physical PSD constraint.
        R_next = (
            0.5
            *
            (
                R_next
                +
                R_next.transpose(
                    -1,
                    -2
                )
            )
        )

        # ----------------------------------------------------
        # Amplitude output
        # ----------------------------------------------------

        A_next = self.A_head(
            x
        ).squeeze(
            1
        )

        return {
            "R_next":
                R_next,

            "amplitude_next":
                A_next,
        }

