# ============================================================
# 14. OPTIMIZER
# ============================================================

optimizer = torch.optim.AdamW(
    model.parameters(),
    lr=1e-3,
    weight_decay=1e-4,
)

# Small prototype run
EPOCHS = 5

print(
    "[+] Optimizer: AdamW"
)

print(
    "[+] Learning rate: 1e-3"
)

