# ============================================================
# 9. SPECTRAL CONVOLUTION
# ============================================================

class SpectralConv1D(
    nn.Module
):

    def __init__(
        self,
        in_channels,
        out_channels,
        modes,
    ):

        super().__init__()

        self.in_channels = (
            in_channels
        )

        self.out_channels = (
            out_channels
        )

        self.modes = (
            modes
        )

        scale = (
            1.0
            /
            math.sqrt(
                in_channels
                *
                out_channels
            )
        )

        self.weight_real = nn.Parameter(
            scale
            *
            torch.randn(
                in_channels,
                out_channels,
                modes
            )
        )

        self.weight_imag = nn.Parameter(
            scale
            *
            torch.randn(
                in_channels,
                out_channels,
                modes
            )
        )

    def forward(
        self,
        x
    ):

        B, C, NX_local = (
            x.shape
        )

        x_ft = torch.fft.rfft(
            x,
            dim=-1
        )

        n_modes = min(
            self.modes,
            x_ft.shape[-1]
        )

        out_ft = torch.zeros(
            B,
            self.out_channels,
            x_ft.shape[-1],
            dtype=torch.complex64,
            device=x.device
        )

        weight = torch.complex(
            self.weight_real[
                :,
                :,
                :n_modes
            ],
            self.weight_imag[
                :,
                :,
                :n_modes
            ]
        )

        out_ft[
            ...,
            :n_modes
        ] = torch.einsum(
            "bim,iom->bom",
            x_ft[
                ...,
                :n_modes
            ],
            weight
        )

        return torch.fft.irfft(
            out_ft,
            n=NX_local,
            dim=-1
        )

# ============================================================
# 10. LINDBLAD KERNEL
# ============================================================

class LindbladDissipativeKernel(
    nn.Module
):

    """
    Learnable Lindblad-form dissipative forward operator.

    D(R) =
        Σ_k [
            L_k R L_k^T
            -
            1/2{
                L_k^T L_k,
                R
            }
        ]

    Environmental coupling gamma(x) explicitly modulates
    the dissipative evolution.

    This is NOT a loss-function regularizer.
    """

    def __init__(
        self,
        dim=6,
        channels=4,
    ):

        super().__init__()

        self.dim = dim
        self.channels = channels

        self.jump_operators = nn.Parameter(
            0.02
            *
            torch.randn(
                channels,
                dim,
                dim
            )
        )

        self.raw_alpha = nn.Parameter(
            torch.tensor(
                0.0
            )
        )

    def positive_alpha(
        self
    ):

        return F.softplus(
            self.raw_alpha
        )

    def dissipator(
        self,
        R
    ):

        total = torch.zeros_like(
            R
        )

        for k in range(
            self.channels
        ):

            L = self.jump_operators[
                k
            ]

            LT = L.transpose(
                -1,
                -2
            )

            A = (
                LT
                @
                L
            )

            jump_term = (
                L
                @
                R
                @
                LT
            )

            anti_term = (
                A
                @
                R
                +
                R
                @
                A
            )

            total = (
                total
                +
                jump_term
                -
                0.5
                *
                anti_term
            )

        return total

    def forward(
        self,
        R,
        gamma,
        dt
    ):

        D_R = self.dissipator(
            R
        )

        alpha = self.positive_alpha()

        gamma_field = gamma[
            ...,
            None,
            None
        ]

        R_next = (
            R
            +
            dt
            *
            alpha
            *
            gamma_field
            *
            D_R
        )

        return (
            R_next,
            D_R
        )

# ============================================================
# 11. LNO MODEL
# ============================================================

class LNOPrototype(
    nn.Module
):

    """
    Spatial Lindblad Neural Operator.

    Fourier layers learn global spatial transformations.

    Lindblad kernel supplies structured dissipative dynamics
    directly inside the forward evolution.
    """

    def __init__(
        self,
        dim=6,
        width=64,
        modes=16,
        depth=4,
        lindblad_channels=4,
    ):

        super().__init__()

        self.dim = dim
        self.width = width
        self.modes = modes
        self.depth = depth

        input_channels = (
            dim * dim
            +
            3
        )

        self.input_projection = nn.Conv1d(
            input_channels,
            width,
            1
        )

        self.spectral_layers = nn.ModuleList(
            [
                SpectralConv1D(
                    width,
                    width,
                    modes
                )
                for _ in range(
                    depth
                )
            ]
        )

        self.pointwise_layers = nn.ModuleList(
            [
                nn.Conv1d(
                    width,
                    width,
                    1
                )
                for _ in range(
                    depth
                )
            ]
        )

        self.lindblad_kernel = (
            LindbladDissipativeKernel(
                dim=dim,
                channels=lindblad_channels
            )
        )

        self.R_head = nn.Conv1d(
            width,
            dim * dim,
            1
        )

        self.A_head = nn.Conv1d(
            width,
            1,
            1
        )

    # --------------------------------------------------------
    # PSD / trace projection
    # --------------------------------------------------------

    def project_R(
        self,
        M
    ):

        M = (
            0.5
            *
            (
                M
                +
                M.transpose(
                    -1,
                    -2
                )
            )
        )

        eigvals, eigvecs = torch.linalg.eigh(
            M
        )

        eigvals = torch.clamp(
            eigvals,
            min=1e-8
        )

        M_psd = (
            eigvecs
            *
            eigvals.unsqueeze(
                -2
            )
        ) @ eigvecs.transpose(
            -1,
            -2
        )

        trace = torch.diagonal(
            M_psd,
            dim1=-2,
            dim2=-1
        ).sum(
            dim=-1,
            keepdim=True
        )

        M_psd = (
            M_psd
            /
            (
                trace.unsqueeze(
                    -1
                )
                +
                1e-12
            )
        )

        return M_psd

    def forward(
        self,
        R,
        amplitude,
        gamma,
        sigma,
        dt=1e-3,
    ):

        B, NX_local, D, D2 = (
            R.shape
        )

        assert D == self.dim
        assert D2 == self.dim

        # ====================================================
        # A. Build input field
        # ====================================================

        R_flat = R.reshape(
            B,
            NX_local,
            D * D
        )

        assert amplitude.shape == (
            B,
            NX_local
        )

        assert gamma.shape == (
            B,
            NX_local
        )

        assert sigma.shape == (
            B,
            NX_local
        )

        env = torch.stack(
            [
                amplitude,
                gamma,
                sigma,
            ],
            dim=-1
        )

        inp = torch.cat(
            [
                R_flat,
                env,
            ],
            dim=-1
        )

        # ====================================================
        # B. Fourier representation
        # ====================================================

        x = inp.permute(
            0,
            2,
            1
        )

        x = self.input_projection(
            x
        )

        spectral_history = []

        for k in range(
            self.depth
        ):

            spectral = (
                self.spectral_layers[k](
                    x
                )
            )

            pointwise = (
                self.pointwise_layers[k](
                    x
                )
            )

            x = (
                spectral
                +
                pointwise
            )

            spectral_history.append(
                torch.linalg.vector_norm(
                    x,
                    dim=(1, 2)
                )
            )

            if k < (
                self.depth - 1
            ):

                x = F.gelu(
                    x
                )

        # ====================================================
        # C. Neural R tendency
        # ====================================================

        neural_R = self.R_head(
            x
        )

        neural_R = (
            neural_R
            .permute(
                0,
                2,
                1
            )
            .reshape(
                B,
                NX_local,
                D,
                D
            )
        )

        neural_R = (
            0.5
            *
            (
                neural_R
                +
                neural_R.transpose(
                    -1,
                    -2
                )
            )
        )

        # Normalize neural tendency
        neural_norm = torch.linalg.vector_norm(
            neural_R,
            dim=(-2, -1),
            keepdim=True
        )

        neural_R = (
            neural_R
            /
            (
                neural_norm
                +
                1e-8
            )
        )

        # ====================================================
        # D. Lindblad forward dynamics
        # ====================================================

        R_lindblad, D_R = (
            self.lindblad_kernel(
                R,
                gamma,
                dt
            )
        )

        # Small neural correction during prototype
        neural_scale = 0.05

        R_candidate = (
            R_lindblad
            +
            dt
            *
            neural_scale
            *
            neural_R
        )

        # ====================================================
        # E. Constrained state projection
        # ====================================================

        R_next = self.project_R(
            R_candidate
        )

        # ====================================================
        # F. Amplitude evolution
        # ====================================================

        A_tendency = self.A_head(
            x
        ).squeeze(
            1
        )

        A_tendency = torch.tanh(
            A_tendency
        )

        log_A = torch.log(
            amplitude
            +
            1e-8
        )

        log_A_next = (
            log_A
            +
            dt
            *
            A_tendency
        )

        amplitude_next = torch.exp(
            log_A_next
        )

        return {

            "R_next":
                R_next,

            "amplitude_next":
                amplitude_next,

            "lindblad_dissipation":
                D_R,

            "spectral_history":
                spectral_history,
        }

# ============================================================
# 12. CREATE MODEL
# ============================================================

model = (
    LNOPrototype(
        dim=6,
        width=64,
        modes=16,
        depth=4,
        lindblad_channels=4,
    )
    .to(device)
)

parameter_count = sum(
    p.numel()
    for p in model.parameters()
)

print(
    "\n[+] LNO parameters:",
    f"{parameter_count:,}"
)

print(
    "[+] Lindblad jump operators:",
    tuple(
        model
        .lindblad_kernel
        .jump_operators
        .shape
    )
)

print(
    "[+] Initial alpha:",
    model
    .lindblad_kernel
    .positive_alpha()
    .item()
)

# ============================================================
# 13. OPTIMIZER
# ============================================================

optimizer = torch.optim.AdamW(
    model.parameters(),
    lr=1e-3,
    weight_decay=1e-4,
)

EPOCHS = 5

print(
    "[+] Optimizer: AdamW"
)

print(
    "[+] LR: 1e-3"
)

print(
    "[+] Weight decay: 1e-4"
)

print(
    "[+] Prototype epochs:",
    EPOCHS
)

# ============================================================
# 14. OUTPUT DIRECTORY
# ============================================================

OUT_DIR = (
    ROOT
    / "results"
    / "step11_lno_prototype"
)

OUT_DIR.mkdir(
    parents=True,
    exist_ok=True
)

BEST_MODEL_PATH = (
    OUT_DIR
    / "lno_prototype_best.pt"
)

# ============================================================
# 15. TRAINING HISTORY
# ============================================================

history = []

best_val_loss = float(
    "inf"
)

best_epoch = None

# ============================================================
# 16. TRAIN
# ============================================================

print(
    "\n" + "=" * 100
)

print(
    "STARTING LNO PROTOTYPE TRAINING"
)

print(
    "=" * 100
)

for epoch in range(
    1,
    EPOCHS + 1
):

    start_time = time.time()

    # ========================================================
    # TRAIN
    # ========================================================

    model.train()

    train_total = 0.0
    train_R_total = 0.0
    train_A_total = 0.0

    train_count = 0

    for (
        R_x,
        A_x,
        env_x,
        R_y,
        A_y,
    ) in train_loader:

        optimizer.zero_grad(
            set_to_none=True
        )

        gamma_x = env_x[
            ...,
            0
        ]

        sigma_x = env_x[
            ...,
            1
        ]

        output = model(
            R_x,
            A_x,
            gamma_x,
            sigma_x,
            dt=1e-3
        )

        R_pred = output[
            "R_next"
        ]

        A_pred = output[
            "amplitude_next"
        ]

        R_loss = F.mse_loss(
            R_pred,
            R_y
        )

        A_loss = F.mse_loss(
            A_pred,
            A_y
        )

        loss = (
            R_loss
            +
            A_loss
        )

        loss.backward()

        torch.nn.utils.clip_grad_norm_(
            model.parameters(),
            max_norm=1.0
        )

        optimizer.step()

        batch_n = R_x.shape[0]

        train_total += (
            loss.item()
            *
            batch_n
        )

        train_R_total += (
            R_loss.item()
            *
            batch_n
        )

        train_A_total += (
            A_loss.item()
            *
            batch_n
        )

        train_count += batch_n

    train_loss = (
        train_total
        /
        train_count
    )

    train_R_loss = (
        train_R_total
        /
        train_count
    )

    train_A_loss = (
        train_A_total
        /
        train_count
    )

    # ========================================================
    # VALIDATION
    # ========================================================

    model.eval()

    val_total = 0.0
    val_R_total = 0.0
    val_A_total = 0.0

    val_count = 0

    with torch.no_grad():

        for (
            R_x,
            A_x,
            env_x,
            R_y,
            A_y,
        ) in val_loader:

            gamma_x = env_x[
                ...,
                0
            ]

            sigma_x = env_x[
                ...,
                1
            ]

            output = model(
                R_x,
                A_x,
                gamma_x,
                sigma_x,
                dt=1e-3
            )

            R_pred = output[
                "R_next"
            ]

            A_pred = output[
                "amplitude_next"
            ]

            R_loss = F.mse_loss(
                R_pred,
                R_y
            )

            A_loss = F.mse_loss(
                A_pred,
                A_y
            )

            loss = (
                R_loss
                +
                A_loss
            )

            batch_n = R_x.shape[0]

            val_total += (
                loss.item()
                *
                batch_n
            )

            val_R_total += (
                R_loss.item()
                *
                batch_n
            )

            val_A_total += (
                A_loss.item()
                *
                batch_n
            )

            val_count += batch_n

    val_loss = (
        val_total
        /
        val_count
    )

    val_R_loss = (
        val_R_total
        /
        val_count
    )

    val_A_loss = (
        val_A_total
        /
        val_count
    )

    elapsed = (
        time.time()
        -
        start_time
    )

    alpha_value = (
        model
        .lindblad_kernel
        .positive_alpha()
        .item()
    )

    history.append({

        "epoch":
            int(epoch),

        "train_loss":
            float(train_loss),

        "train_R_loss":
            float(train_R_loss),

        "train_amplitude_loss":
            float(train_A_loss),

        "val_loss":
            float(val_loss),

        "val_R_loss":
            float(val_R_loss),

        "val_amplitude_loss":
            float(val_A_loss),

        "alpha":
            float(alpha_value),

        "time_seconds":
            float(elapsed),
    })

    print(
        f"\nEpoch {epoch:02d}/{EPOCHS}"
    )

    print(
        f"  Train loss       : {train_loss:.12e}"
    )

    print(
        f"  Train R loss     : {train_R_loss:.12e}"
    )

    print(
        f"  Train amplitude  : {train_A_loss:.12e}"
    )

    print(
        f"  Val loss         : {val_loss:.12e}"
    )

    print(
        f"  Val R loss       : {val_R_loss:.12e}"
    )

    print(
        f"  Val amplitude    : {val_A_loss:.12e}"
    )

    print(
        f"  Alpha            : {alpha_value:.8e}"
    )

    print(
        f"  Time             : {elapsed:.2f}s"
    )

    # ========================================================
    # BEST CHECKPOINT
    # ========================================================

    if val_loss < best_val_loss:

        best_val_loss = (
            val_loss
        )

        best_epoch = (
            epoch
        )

        torch.save(
            {

                "model_state_dict":
                    model.state_dict(),

                "optimizer_state_dict":
                    optimizer.state_dict(),

                "epoch":
                    int(epoch),

                "val_loss":
                    float(val_loss),

                "architecture":
                    {

                        "name":
                            "LNOPrototype",

                        "dim":
                            6,

                        "width":
                            64,

                        "modes":
                            16,

                        "depth":
                            4,

                        "lindblad_channels":
                            4,
                    },

                "representation":
                    {

                        "R":
                            "z z^T / Tr(z z^T)",

                        "amplitude":
                            "full-information amplitude in Dataset V3",
                    },

                "lindblad_in_forward_path":
                    True,

                "prototype":
                    True,
            },
            BEST_MODEL_PATH
        )

        print(
            "  >>> NEW BEST LNO CHECKPOINT SAVED"
        )

# ============================================================
# 17. SAVE HISTORY
