# ============================================================
# 11. SPECTRAL CONVOLUTION
# ============================================================

class SpectralConv1D(
    nn.Module
):

    def __init__(
        self,
        in_channels,
        out_channels,
        modes,
    ):

        super().__init__()

        self.in_channels = (
            in_channels
        )

        self.out_channels = (
            out_channels
        )

        self.modes = (
            modes
        )

        scale = (
            1.0
            /
            math.sqrt(
                in_channels
                *
                out_channels
            )
        )

        self.weight_real = nn.Parameter(
            scale
            *
            torch.randn(
                in_channels,
                out_channels,
                modes
            )
        )

        self.weight_imag = nn.Parameter(
            scale
            *
            torch.randn(
                in_channels,
                out_channels,
                modes
            )
        )

    def forward(
        self,
        x
    ):

        B, C, NX_local = x.shape

        x_ft = torch.fft.rfft(
            x,
            dim=-1
        )

        n_modes = min(
            self.modes,
            x_ft.shape[-1]
        )

        out_ft = torch.zeros(
            B,
            self.out_channels,
            x_ft.shape[-1],
            dtype=torch.complex64,
            device=x.device
        )

        weight = torch.complex(
            self.weight_real[
                ...,
                :n_modes
            ],
            self.weight_imag[
                ...,
                :n_modes
            ]
        )

        out_ft[
            ...,
            :n_modes
        ] = torch.einsum(
            "bim,iom->bom",
            x_ft[
                ...,
                :n_modes
            ],
            weight
        )

        return torch.fft.irfft(
            out_ft,
            n=NX_local,
            dim=-1
        )


# ============================================================
# 12. LINDBLAD KERNEL
# ============================================================

class LindbladDissipativeKernel(
    nn.Module
):

    def __init__(
        self,
        dim=6,
        channels=4,
    ):

        super().__init__()

        self.dim = dim
        self.channels = channels

        self.jump_operators = nn.Parameter(
            0.02
            *
            torch.randn(
                channels,
                dim,
                dim
            )
        )

        self.raw_alpha = nn.Parameter(
            torch.tensor(
                0.0
            )
        )

    def positive_alpha(
        self
    ):

        return F.softplus(
            self.raw_alpha
        )

    def dissipator(
        self,
        R
    ):

        total = torch.zeros_like(
            R
        )

        for k in range(
            self.channels
        ):

            L = self.jump_operators[
                k
            ]

            LT = L.transpose(
                -1,
                -2
            )

            A = (
                LT
                @
                L
            )

            jump_term = (
                L
                @
                R
                @
                LT
            )

            anti_term = (
                A
                @
                R
                +
                R
                @
                A
            )

            total = (
                total
                +
                jump_term
                -
                0.5
                *
                anti_term
            )

        return total

    def forward(
        self,
        R,
        gamma,
        dt
    ):

        D_R = self.dissipator(
            R
        )

        alpha = (
            self.positive_alpha()
        )

        gamma_field = gamma[
            ...,
            None,
            None
        ]

        R_next = (
            R
            +
            dt
            *
            alpha
            *
            gamma_field
            *
            D_R
        )

        return (
            R_next,
            D_R
        )


# ============================================================
# 13. SHARED PSD / TRACE PROJECTION
# ============================================================

def project_R(
    M
):

    M = (
        0.5
        *
        (
            M
            +
            M.transpose(
                -1,
                -2
            )
        )
    )

    eigvals, eigvecs = torch.linalg.eigh(
        M
    )

    eigvals = torch.clamp(
        eigvals,
        min=1e-8
    )

    M_psd = (
        eigvecs
        *
        eigvals.unsqueeze(
            -2
        )
    ) @ eigvecs.transpose(
        -1,
        -2
    )

    trace = torch.diagonal(
        M_psd,
        dim1=-2,
        dim2=-1
    ).sum(
        dim=-1,
        keepdim=True
    )

    M_psd = (
        M_psd
        /
        (
            trace.unsqueeze(
                -1
            )
            +
            1e-12
        )
    )

    return M_psd


# ============================================================
# 14. A — TRUE FNO BASELINE
# ============================================================

class FNOBaseline(
    nn.Module
):

    def __init__(
        self,
        dim=6,
        width=64,
        modes=16,
        depth=4,
    ):

        super().__init__()

        self.dim = dim
        self.width = width
        self.modes = modes
        self.depth = depth

        # Same task inputs:
        # R + amplitude + gamma + sigma

        input_channels = (
            dim * dim
            +
            3
        )

        self.input_projection = nn.Conv1d(
            input_channels,
            width,
            1
        )

        self.spectral_layers = nn.ModuleList(
            [
                SpectralConv1D(
                    width,
                    width,
                    modes
                )
                for _ in range(
                    depth
                )
            ]
        )

        self.pointwise_layers = nn.ModuleList(
            [
                nn.Conv1d(
                    width,
                    width,
                    1
                )
                for _ in range(
                    depth
                )
            ]
        )

        self.R_head = nn.Conv1d(
            width,
            dim * dim,
            1
        )

        self.A_head = nn.Conv1d(
            width,
            1,
            1
        )

    def forward(
        self,
        R,
        amplitude,
        gamma,
        sigma,
        dt=1e-3,
    ):

        B, NX_local, D, D2 = R.shape

        R_flat = R.reshape(
            B,
            NX_local,
            D * D
        )

        env = torch.stack(
            [
                amplitude,
                gamma,
                sigma,
            ],
            dim=-1
        )

        inp = torch.cat(
            [
                R_flat,
                env,
            ],
            dim=-1
        )

        x = inp.permute(
            0,
            2,
            1
        )

        x = self.input_projection(
            x
        )

        for k in range(
            self.depth
        ):

            x = (
                self.spectral_layers[k](
                    x
                )
                +
                self.pointwise_layers[k](
                    x
                )
            )

            if k < self.depth - 1:

                x = F.gelu(
                    x
                )

        R_next = self.R_head(
            x
        )

        R_next = (
            R_next
            .permute(
                0,
                2,
                1
            )
            .reshape(
                B,
                NX_local,
                D,
                D
            )
        )

        # Common symmetric representation.
        # No PSD / trace projection here.
        R_next = (
            0.5
            *
            (
                R_next
                +
                R_next.transpose(
                    -1,
                    -2
                )
            )
        )

        A_next = self.A_head(
            x
        ).squeeze(
            1
        )

        return {

            "R_next":
                R_next,

            "amplitude_next":
                A_next,

            "D_R":
                torch.zeros_like(
                    R
                ),
        }


# ============================================================
# 15. B/C/D LNO ABLATION MODEL
# ============================================================

class AblationLNO(
    nn.Module
):

    def __init__(
        self,
        mode,
        dim=6,
        width=64,
        modes=16,
        depth=4,
        lindblad_channels=4,
    ):

        super().__init__()

        assert mode in {

            "B_no_lindblad",

            "C_lindblad",

            "D_full_lno",
        }

        self.mode = mode

        self.dim = dim
        self.width = width
        self.depth = depth

        # ----------------------------------------------------
        # B / C:
        #   R + amplitude
        #
        # D:
        #   R + amplitude + gamma + sigma
        # ----------------------------------------------------

        if mode == "D_full_lno":

            input_channels = (
                dim * dim
                +
                3
            )

        else:

            input_channels = (
                dim * dim
                +
                1
            )

        self.input_projection = nn.Conv1d(
            input_channels,
            width,
            1
        )

        self.spectral_layers = nn.ModuleList(
            [
                SpectralConv1D(
                    width,
                    width,
                    modes
                )
                for _ in range(
                    depth
                )
            ]
        )

        self.pointwise_layers = nn.ModuleList(
            [
                nn.Conv1d(
                    width,
                    width,
                    1
                )
                for _ in range(
                    depth
                )
            ]
        )

        self.R_head = nn.Conv1d(
            width,
            dim * dim,
            1
        )

        self.A_head = nn.Conv1d(
            width,
            1,
            1
        )

        if mode in {

            "C_lindblad",

            "D_full_lno",

        }:

            self.lindblad_kernel = (
                LindbladDissipativeKernel(
                    dim=dim,
                    channels=lindblad_channels
                )
            )

        else:

            self.lindblad_kernel = None

    def forward(
        self,
        R,
        amplitude,
        gamma,
        sigma,
        dt=1e-3,
    ):

        B, NX_local, D, D2 = R.shape

        R_flat = R.reshape(
            B,
            NX_local,
            D * D
        )

        if self.mode == "D_full_lno":

            env = torch.stack(
                [
                    amplitude,
                    gamma,
                    sigma,
                ],
                dim=-1
            )

        else:

            env = amplitude[
                ...,
                None
            ]

        inp = torch.cat(
            [
                R_flat,
                env,
            ],
            dim=-1
        )

        x = inp.permute(
            0,
            2,
            1
        )

        x = self.input_projection(
            x
        )

        for k in range(
            self.depth
        ):

            x = (
                self.spectral_layers[k](
                    x
                )
                +
                self.pointwise_layers[k](
                    x
                )
            )

            if k < self.depth - 1:

                x = F.gelu(
                    x
                )

        neural_R = self.R_head(
            x
        )

        neural_R = (
            neural_R
            .permute(
                0,
                2,
                1
            )
            .reshape(
                B,
                NX_local,
                D,
                D
            )
        )

        neural_R = (
            0.5
            *
            (
                neural_R
                +
                neural_R.transpose(
                    -1,
                    -2
                )
            )
        )

        neural_norm = torch.linalg.vector_norm(
            neural_R,
            dim=(-2, -1),
            keepdim=True
        )

        neural_R = (
            neural_R
            /
            (
                neural_norm
                +
                1e-8
            )
        )

        # ----------------------------------------------------
        # Lindblad branch
        # ----------------------------------------------------

        if self.lindblad_kernel is not None:

            R_lindblad, D_R = (
                self.lindblad_kernel(
                    R,
                    gamma,
                    dt
                )
            )

            candidate = (
                R_lindblad
                +
                dt
                *
                0.05
                *
                neural_R
            )

        else:

            D_R = torch.zeros_like(
                R
            )

            candidate = (
                R
                +
                dt
                *
                0.05
                *
                neural_R
            )

        R_next = project_R(
            candidate
        )

        # ----------------------------------------------------
        # Amplitude
        # ----------------------------------------------------

        A_tendency = self.A_head(
            x
        ).squeeze(
            1
        )

        A_tendency = torch.tanh(
            A_tendency
        )

        log_A = torch.log(
            amplitude
            +
            1e-8
        )

        log_A_next = (
            log_A
            +
            dt
            *
            A_tendency
        )

        A_next = torch.exp(
            log_A_next
        )

        return {

            "R_next":
                R_next,

            "amplitude_next":
                A_next,

            "D_R":
                D_R,
        }


# ============================================================
# 16. FACTORY
# ============================================================

def build_model(
    label
):

    if label == "A_FNO":

        return FNOBaseline(
            dim=6,
            width=64,
            modes=16,
            depth=4,
        ).to(device)

    if label == "B_LNO_no_Lindblad":

        return AblationLNO(
            mode="B_no_lindblad",
            dim=6,
            width=64,
            modes=16,
            depth=4,
        ).to(device)

    if label == "C_LNO_Lindblad":

        return AblationLNO(
            mode="C_lindblad",
            dim=6,
            width=64,
            modes=16,
            depth=4,
            lindblad_channels=4,
        ).to(device)

    if label == "D_Full_LNO":

        return AblationLNO(
            mode="D_full_lno",
            dim=6,
            width=64,
            modes=16,
            depth=4,
            lindblad_channels=4,
        ).to(device)

    raise ValueError(
        f"Unknown model: {label}"
    )


# ============================================================
# 17. TRAIN ONE MODEL
# ============================================================

def train_one_model(
    model,
    epochs=5,
):

    optimizer = torch.optim.AdamW(
        model.parameters(),
        lr=1e-3,
        weight_decay=1e-4,
    )

    best_val = float(
        "inf"
    )

    best_epoch = None

    best_state = None

    history = []

    for epoch in range(
        1,
        epochs + 1
    ):

        start_time = time.time()

        # ----------------------------------------------------
        # TRAIN
        # ----------------------------------------------------

        model.train()

        total_sum = 0.0
        R_sum = 0.0
        A_sum = 0.0
        count = 0

        for (
            R_x,
            A_x,
            env_x,
            R_y,
            A_y,
        ) in train_loader:

            R_x = R_x.to(
                device
            )

            A_x = A_x.to(
                device
            )

            env_x = env_x.to(
                device
            )

            R_y = R_y.to(
                device
            )

            A_y = A_y.to(
                device
            )

            gamma_x = env_x[
                ...,
                0
            ]

            sigma_x = env_x[
                ...,
                1
            ]

            optimizer.zero_grad(
                set_to_none=True
            )

            out = model(
                R_x,
                A_x,
                gamma_x,
                sigma_x,
                dt=1e-3
            )

            R_loss = F.mse_loss(
                out[
                    "R_next"
                ],
                R_y
            )

            A_loss = F.mse_loss(
                out[
                    "amplitude_next"
                ],
                A_y
            )

            loss = (
                R_loss
                +
                A_loss
            )

            loss.backward()

            torch.nn.utils.clip_grad_norm_(
                model.parameters(),
                max_norm=1.0
            )

            optimizer.step()

            n_batch = R_x.shape[0]

            total_sum += (
                loss.item()
                *
                n_batch
            )

            R_sum += (
                R_loss.item()
                *
                n_batch
            )

            A_sum += (
                A_loss.item()
                *
                n_batch
            )

            count += n_batch

        train_loss = (
            total_sum
            /
            count
        )

        train_R = (
            R_sum
            /
            count
        )

        train_A = (
            A_sum
            /
            count
        )

        # ----------------------------------------------------
        # VALIDATION
        # ----------------------------------------------------

        model.eval()

        val_sum = 0.0
        val_R_sum = 0.0
        val_A_sum = 0.0
        val_count = 0

        with torch.no_grad():

            for (
                R_x,
                A_x,
                env_x,
                R_y,
                A_y,
            ) in val_loader:

                R_x = R_x.to(
                    device
                )

                A_x = A_x.to(
                    device
                )

                env_x = env_x.to(
                    device
                )

                R_y = R_y.to(
                    device
                )

                A_y = A_y.to(
                    device
                )

                gamma_x = env_x[
                    ...,
                    0
                ]

                sigma_x = env_x[
                    ...,
                    1
                ]

                out = model(
                    R_x,
                    A_x,
                    gamma_x,
                    sigma_x,
                    dt=1e-3
                )

                R_loss = F.mse_loss(
                    out[
                        "R_next"
                    ],
                    R_y
                )

                A_loss = F.mse_loss(
                    out[
                        "amplitude_next"
                    ],
                    A_y
                )

                loss = (
                    R_loss
                    +
                    A_loss
                )

                n_batch = R_x.shape[0]

                val_sum += (
                    loss.item()
                    *
                    n_batch
                )

                val_R_sum += (
                    R_loss.item()
                    *
                    n_batch
                )

                val_A_sum += (
                    A_loss.item()
                    *
                    n_batch
                )

                val_count += n_batch

        val_loss = (
            val_sum
            /
            val_count
        )

        val_R = (
            val_R_sum
            /
            val_count
        )

        val_A = (
            val_A_sum
            /
            val_count
        )

        elapsed = (
            time.time()
            -
            start_time
        )

        history.append({

            "epoch":
                int(epoch),

            "train_loss":
                float(train_loss),

            "train_R_loss":
                float(train_R),

            "train_amplitude_loss":
                float(train_A),

            "val_loss":
                float(val_loss),

            "val_R_loss":
                float(val_R),

            "val_amplitude_loss":
                float(val_A),

            "time_seconds":
                float(elapsed),
        })

        print(
            f"    Epoch {epoch:02d}/{epochs}"
            f" | train={train_loss:.6e}"
            f" | val={val_loss:.6e}"
            f" | time={elapsed:.2f}s"
        )

        # ----------------------------------------------------
        # Best state
        # ----------------------------------------------------

        if val_loss < best_val:

            best_val = (
                val_loss
            )

            best_epoch = (
                epoch
            )

            best_state = {

                key:
                    value.detach()
                    .cpu()
                    .clone()

                for key, value
                in model.state_dict().items()
            }

    # Restore best state
    if best_state is not None:

        model.load_state_dict(
            best_state
        )

    return (
        history,
        best_val,
        best_epoch
    )


# ============================================================
# 18. EVALUATION
# ============================================================

def evaluate_model(
    model,
):

    model.eval()

    with torch.no_grad():

        R_x = X_R_test_t.to(
            device
        )

        A_x = X_A_test_t.to(
            device
        )

        env_x = ENV_test_t.to(
            device
        )

        R_y = Y_R_test_t.to(
            device
        )

        A_y = Y_A_test_t.to(
            device
        )

        gamma_x = env_x[
            ...,
            0
        ]

        sigma_x = env_x[
            ...,
            1
        ]

        out = model(
            R_x,
            A_x,
            gamma_x,
            sigma_x,
            dt=1e-3
        )

        R_pred = out[
            "R_next"
        ]

        A_pred = out[
            "amplitude_next"
        ]

    # --------------------------------------------------------
    # Errors
    # --------------------------------------------------------

    R_error = (
        R_pred
        -
        R_y
    )

    A_error = (
        A_pred
        -
        A_y
    )

    R_mse = torch.mean(
        R_error ** 2
    )

    R_rmse = torch.sqrt(
        R_mse
        +
        1e-12
    )

    R_mae = torch.mean(
        torch.abs(
            R_error
        )
    )

    R_rel_l2 = (
        torch.linalg.vector_norm(
            R_error
        )
        /
        (
            torch.linalg.vector_norm(
                R_y
            )
            +
            1e-12
        )
    )

    A_mse = torch.mean(
        A_error ** 2
    )

    A_rmse = torch.sqrt(
        A_mse
        +
        1e-12
    )

    A_mae = torch.mean(
        torch.abs(
            A_error
        )
    )

    A_rel_l2 = (
        torch.linalg.vector_norm(
            A_error
        )
        /
        (
            torch.linalg.vector_norm(
                A_y
            )
            +
            1e-12
        )
    )

    # --------------------------------------------------------
    # Structural output
    # --------------------------------------------------------

    trace = torch.diagonal(
        R_pred,
        dim1=-2,
        dim2=-1
    ).sum(
        dim=-1
    )

    trace_mean_error = float(
        torch.mean(
            torch.abs(
                trace
                -
                1.0
            )
        ).item()
    )

    trace_max_error = float(
        torch.max(
            torch.abs(
                trace
                -
                1.0
            )
        ).item()
    )

    symmetry_error = float(
        torch.max(
            torch.abs(
                R_pred
                -
                R_pred.transpose(
                    -1,
                    -2
                )
            )
        ).item()
    )

    eigenvalues = torch.linalg.eigvalsh(
        R_pred
    )

    min_eigenvalue = float(
        eigenvalues.min().item()
    )

    finite = bool(
        torch.isfinite(
            R_pred
        ).all().item()
        and
        torch.isfinite(
            A_pred
        ).all().item()
    )

    # --------------------------------------------------------
    # Environment response
    # --------------------------------------------------------

    probe_R = R_x[
        :1
    ]

    probe_A = A_x[
        :1
    ]

    probe_sigma = sigma_x[
        :1
    ]

    env_rows = []

    for gamma_value in [
        0.0,
        0.01,
        0.05,
        0.15,
        0.35,
        0.50,
    ]:

        gamma_probe = torch.full_like(
            gamma_x[
                :1
            ],
            gamma_value
        )

        out_env = model(
            probe_R,
            probe_A,
            gamma_probe,
            probe_sigma,
            dt=1e-3
        )

        r_change = float(
            torch.linalg.vector_norm(
                out_env[
                    "R_next"
                ]
                -
                probe_R
            ).item()
        )

        a_change = float(
            torch.linalg.vector_norm(
                out_env[
                    "amplitude_next"
                ]
                -
                probe_A
            ).item()
        )

        d_norm = float(
            torch.linalg.vector_norm(
                out_env[
                    "D_R"
                ]
            ).item()
        )

        env_rows.append({

            "gamma":
                float(
                    gamma_value
                ),

            "R_change":
                r_change,

            "amplitude_change":
                a_change,

            "Lindblad_D_norm":
                d_norm,
        })

    env_df = pd.DataFrame(
        env_rows
    )

    return {

        "R_MSE":
            float(
                R_mse.item()
            ),

        "R_RMSE":
            float(
                R_rmse.item()
            ),

        "R_MAE":
            float(
                R_mae.item()
            ),

        "R_relative_L2":
            float(
                R_rel_l2.item()
            ),

        "A_MSE":
            float(
                A_mse.item()
            ),

        "A_RMSE":
            float(
                A_rmse.item()
            ),

        "A_MAE":
            float(
                A_mae.item()
            ),

        "A_relative_L2":
            float(
                A_rel_l2.item()
            ),

        "trace_mean_error":
            trace_mean_error,

        "trace_max_error":
            trace_max_error,

        "symmetry_error":
            symmetry_error,

        "minimum_eigenvalue":
            min_eigenvalue,

        "finite":
            finite,

        "environment":
            env_df,

        "R_prediction":
            R_pred.detach()
            .cpu()
            .numpy(),

        "A_prediction":
            A_pred.detach()
            .cpu()
            .numpy(),
    }


