# ============================================================
# 20. GRADIENT DIAGNOSTIC
# ============================================================

def gradient_diagnostic(
    model
):

    model.train()

    model.zero_grad(
        set_to_none=True
    )

    R_sample = (
        X_R_train_t[
            :BATCH_SIZE
        ]
        .to(device)
        .detach()
        .clone()
        .requires_grad_()
    )

    A_sample = (
        X_A_train_t[
            :BATCH_SIZE
        ]
        .to(device)
        .detach()
        .clone()
        .requires_grad_()
    )

    env_sample = (
        ENV_train_t[
            :BATCH_SIZE
        ]
        .to(device)
    )

    gamma_sample = env_sample[
        ...,
        0
    ]

    sigma_sample = env_sample[
        ...,
        1
    ]

    R_target_sample = (
        Y_R_train_t[
            :BATCH_SIZE
        ]
        .to(device)
    )

    A_target_sample = (
        Y_A_train_t[
            :BATCH_SIZE
        ]
        .to(device)
    )

    out = model(
        R_sample,
        A_sample,
        gamma_sample,
        sigma_sample,
        dt=1e-3
    )

    loss = (
        F.mse_loss(
            out[
                "R_next"
            ],
            R_target_sample
        )
        +
        F.mse_loss(
            out[
                "amplitude_next"
            ],
            A_target_sample
        )
    )

    loss.backward()

    result = {

        "gradient_loss":
            float(
                loss.item()
            ),

        "input_R_gradient":
            float(
                torch.linalg.vector_norm(
                    R_sample.grad
                ).item()
            ),

        "input_A_gradient":
            float(
                torch.linalg.vector_norm(
                    A_sample.grad
                ).item()
            ),

    }

    if hasattr(
        model,
        "lindblad_kernel"
    ):

        if model.lindblad_kernel is not None:

            jump_grad = (
                model
                .lindblad_kernel
                .jump_operators
                .grad
            )

            alpha_grad = (
                model
                .lindblad_kernel
                .raw_alpha
                .grad
            )

            result[
                "jump_gradient_L2"
            ] = float(
                torch.linalg.vector_norm(
                    jump_grad
                ).item()
            )

            result[
                "alpha_gradient"
            ] = float(
                torch.abs(
                    alpha_grad
                ).item()
            )

        else:

            result[
                "jump_gradient_L2"
            ] = 0.0

            result[
                "alpha_gradient"
            ] = 0.0

    else:

        result[
            "jump_gradient_L2"
        ] = 0.0

        result[
            "alpha_gradient"
        ] = 0.0

    return result


