# ============================================================
# 8. SPECTRAL CONVOLUTION
# ============================================================

class SpectralConv1D(
    nn.Module
):

    def __init__(
        self,
        in_channels,
        out_channels,
        modes,
    ):

        super().__init__()

        self.in_channels = in_channels
        self.out_channels = out_channels
        self.modes = modes

        scale = (
            1.0
            /
            math.sqrt(
                in_channels
                *
                out_channels
            )
        )

        self.weight_real = nn.Parameter(
            scale
            *
            torch.randn(
                in_channels,
                out_channels,
                modes
            )
        )

        self.weight_imag = nn.Parameter(
            scale
            *
            torch.randn(
                in_channels,
                out_channels,
                modes
            )
        )

    def forward(
        self,
        x
    ):

        B, C, NX_local = x.shape

        x_ft = torch.fft.rfft(
            x,
            dim=-1
        )

        n_modes = min(
            self.modes,
            x_ft.shape[-1]
        )

        out_ft = torch.zeros(
            B,
            self.out_channels,
            x_ft.shape[-1],
            dtype=torch.complex64,
            device=x.device
        )

        weight = torch.complex(
            self.weight_real[
                ...,
                :n_modes
            ],
            self.weight_imag[
                ...,
                :n_modes
            ]
        )

        out_ft[
            ...,
            :n_modes
        ] = torch.einsum(
            "bim,iom->bom",
            x_ft[
                ...,
                :n_modes
            ],
            weight
        )

        return torch.fft.irfft(
            out_ft,
            n=NX_local,
            dim=-1
        )


# ============================================================
# 9. LINDBLAD KERNEL
# ============================================================

class LindbladDissipativeKernel(
    nn.Module
):

    def __init__(
        self,
        dim=6,
        channels=4,
    ):

        super().__init__()

        self.dim = dim
        self.channels = channels

        self.jump_operators = nn.Parameter(
            0.02
            *
            torch.randn(
                channels,
                dim,
                dim
            )
        )

        self.raw_alpha = nn.Parameter(
            torch.tensor(
                0.0
            )
        )

    def positive_alpha(
        self
    ):

        return F.softplus(
            self.raw_alpha
        )

    def dissipator(
        self,
        R
    ):

        total = torch.zeros_like(
            R
        )

        for k in range(
            self.channels
        ):

            L = self.jump_operators[
                k
            ]

            LT = L.transpose(
                -1,
                -2
            )

            A = (
                LT
                @
                L
            )

            jump = (
                L
                @
                R
                @
                LT
            )

            anti = (
                A
                @
                R
                +
                R
                @
                A
            )

            total = (
                total
                +
                jump
                -
                0.5
                *
                anti
            )

        return total

    def forward(
        self,
        R,
        gamma,
        dt
    ):

        D_R = self.dissipator(
            R
        )

        alpha = self.positive_alpha()

        gamma_field = (
            gamma[
                ...,
                None,
                None
            ]
        )

        R_lindblad = (
            R
            +
            dt
            *
            alpha
            *
            gamma_field
            *
            D_R
        )

        return (
            R_lindblad,
            D_R
        )


# ============================================================
# 10. LNO MODEL
# ============================================================

class LNOPrototype(
    nn.Module
):

    def __init__(
        self,
        dim=6,
        width=64,
        modes=16,
        depth=4,
        lindblad_channels=4,
    ):

        super().__init__()

        self.dim = dim

        self.width = width

        self.modes = modes

        self.depth = depth

        input_channels = (
            dim * dim
            +
            3
        )

        self.input_projection = nn.Conv1d(
            input_channels,
            width,
            1
        )

        self.spectral_layers = nn.ModuleList(
            [
                SpectralConv1D(
                    width,
                    width,
                    modes
                )
                for _ in range(
                    depth
                )
            ]
        )

        self.pointwise_layers = nn.ModuleList(
            [
                nn.Conv1d(
                    width,
                    width,
                    1
                )
                for _ in range(
                    depth
                )
            ]
        )

        self.lindblad_kernel = (
            LindbladDissipativeKernel(
                dim=dim,
                channels=lindblad_channels
            )
        )

        self.R_head = nn.Conv1d(
            width,
            dim * dim,
            1
        )

        self.A_head = nn.Conv1d(
            width,
            1,
            1
        )

    def neural_tendency(
        self,
        R,
        amplitude,
        gamma,
        sigma
    ):

        B, NX_local, D, D2 = R.shape

        R_flat = R.reshape(
            B,
            NX_local,
            D * D
        )

        env = torch.stack(
            [
                amplitude,
                gamma,
                sigma,
            ],
            dim=-1
        )

        inp = torch.cat(
            [
                R_flat,
                env,
            ],
            dim=-1
        )

        x = inp.permute(
            0,
            2,
            1
        )

        x = self.input_projection(
            x
        )

        for k in range(
            self.depth
        ):

            x = (
                self.spectral_layers[k](
                    x
                )
                +
                self.pointwise_layers[k](
                    x
                )
            )

            if k < self.depth - 1:

                x = F.gelu(
                    x
                )

        neural_R = self.R_head(
            x
        )

        neural_R = (
            neural_R
            .permute(
                0,
                2,
                1
            )
            .reshape(
                B,
                NX_local,
                D,
                D
            )
        )

        neural_R = (
            0.5
            *
            (
                neural_R
                +
                neural_R.transpose(
                    -1,
                    -2
                )
            )
        )

        # Direction only for calibration.
        norm = torch.linalg.vector_norm(
            neural_R,
            dim=(-2, -1),
            keepdim=True
        )

        neural_direction = (
            neural_R
            /
            (
                norm
                +
                1e-8
            )
        )

        return neural_direction

    def forward_components(
        self,
        R,
        amplitude,
        gamma,
        sigma,
        dt
    ):

        neural_direction = (
            self.neural_tendency(
                R,
                amplitude,
                gamma,
                sigma
            )
        )

        R_lindblad, D_R = (
            self.lindblad_kernel(
                R,
                gamma,
                dt
            )
        )

        delta_lindblad = (
            R_lindblad
            -
            R
        )

        return (
            delta_lindblad,
            neural_direction,
            D_R
        )


