# ============================================================
# 10. TRAJECTORY-LEVEL STRATIFIED SPLIT
#
# Each regime:
#   20 trajectories
#
# Split:
#   14 train
#    3 validation
#    3 test
#
# Total:
#   70 / 15 / 15 trajectories
# ============================================================

TRAIN_TRAJECTORIES = []
VAL_TRAJECTORIES = []
TEST_TRAJECTORIES = []

split_rows = []

trajectory_table = (
    metadata[
        [
            "trajectory_id",
            "regime",
            "trajectory_index",
            "gamma",
            "noise_sigma",
            "noise_seed",
        ]
    ]
    .drop_duplicates(
        "trajectory_id"
    )
    .copy()
)

# deterministic regime-wise selection
for regime in regimes:

    regime_table = (
        trajectory_table[
            trajectory_table[
                "regime"
            ]
            ==
            regime
        ]
        .sort_values(
            "trajectory_index"
        )
        .reset_index(
            drop=True
        )
    )

    assert len(
        regime_table
    ) == 20

    # fixed deterministic permutation within each regime
    local_rng = np.random.default_rng(
        SEED
        +
        regimes.index(
            regime
        )
    )

    perm = local_rng.permutation(
        len(
            regime_table
        )
    )

    shuffled = (
        regime_table
        .iloc[
            perm
        ]
        .reset_index(
            drop=True
        )
    )

    train_part = shuffled.iloc[
        :14
    ]

    val_part = shuffled.iloc[
        14:17
    ]

    test_part = shuffled.iloc[
        17:20
    ]

    TRAIN_TRAJECTORIES.extend(
        train_part[
            "trajectory_id"
        ]
        .tolist()
    )

    VAL_TRAJECTORIES.extend(
        val_part[
            "trajectory_id"
        ]
        .tolist()
    )

    TEST_TRAJECTORIES.extend(
        test_part[
            "trajectory_id"
        ]
        .tolist()
    )

