optimizer = torch.optim.AdamW(
    model.parameters(),
    lr=1e-3,
    weight_decay=1e-4
)

scheduler = torch.optim.lr_scheduler.ReduceLROnPlateau(
    optimizer,
    mode="min",
    factor=0.5,
    patience=4
)

MAX_EPOCHS = 40

EARLY_STOPPING_PATIENCE = 8

MIN_DELTA = 1e-6

print(
    "\n[+] Optimizer: AdamW"
)

print(
    "[+] Learning rate: 1e-3"
)

print(
    "[+] Weight decay: 1e-4"
)

print(
    "[+] Maximum epochs:",
    MAX_EPOCHS
)

print(
    "[+] Early stopping patience:",
    EARLY_STOPPING_PATIENCE
)


# ============================================================
# 19. TRAINING
# ============================================================

history = []

best_val_loss = float(
    "inf"
)

best_epoch = None

epochs_without_improvement = 0

print("\n" + "=" * 100)
print("STARTING FINAL LNO TRAINING")
print("=" * 100)

for epoch in range(
    1,
    MAX_EPOCHS + 1
):

    start_time = time.time()

    # ========================================================
    # TRAIN
    # ========================================================

    model.train()

    train_loss_sum = 0.0
    train_R_sum = 0.0
    train_A_sum = 0.0

    train_count = 0

    for (
        R_x,
        A_x,
        env_x,
        R_y,
        A_y
    ) in train_loader:

        R_x = R_x.to(
            device,
            non_blocking=(
                device.type == "cuda"
            )
        )

        A_x = A_x.to(
            device,
            non_blocking=(
                device.type == "cuda"
            )
        )

        env_x = env_x.to(
            device,
            non_blocking=(
                device.type == "cuda"
            )
        )

        R_y = R_y.to(
            device,
            non_blocking=(
                device.type == "cuda"
            )
        )

        A_y = A_y.to(
            device,
            non_blocking=(
                device.type == "cuda"
            )
        )

        gamma_x = env_x[
            ...,
            0
        ]

        sigma_x = env_x[
            ...,
            1
        ]

        optimizer.zero_grad(
            set_to_none=True
        )

        output = model(
            R_x,
            A_x,
            gamma_x,
            sigma_x
        )

        R_pred = output[
            "R_next"
        ]

        A_pred = output[
            "amplitude_next"
        ]

        R_loss = F.mse_loss(
            R_pred,
            R_y
        )

        A_loss = F.mse_loss(
            A_pred,
            A_y
        )

        loss = (
            R_loss
            +
            A_loss
        )

        loss.backward()

        torch.nn.utils.clip_grad_norm_(
            model.parameters(),
            max_norm=1.0
        )

        optimizer.step()

        n_batch = R_x.shape[0]

        train_loss_sum += (
            loss.item()
            *
            n_batch
        )

        train_R_sum += (
            R_loss.item()
            *
            n_batch
        )

        train_A_sum += (
            A_loss.item()
            *
            n_batch
        )

        train_count += n_batch

    train_loss = (
        train_loss_sum
        /
        train_count
    )

    train_R_loss = (
        train_R_sum
        /
        train_count
    )

    train_A_loss = (
        train_A_sum
        /
        train_count
    )

    # ========================================================
    # VALIDATION
    # ========================================================

    model.eval()

    val_loss_sum = 0.0
    val_R_sum = 0.0
    val_A_sum = 0.0

    val_count = 0

    with torch.no_grad():

        for (
            R_x,
            A_x,
            env_x,
            R_y,
            A_y
        ) in val_loader:

            R_x = R_x.to(
                device,
                non_blocking=(
                    device.type == "cuda"
                )
            )

            A_x = A_x.to(
                device,
                non_blocking=(
                    device.type == "cuda"
                )
            )

            env_x = env_x.to(
                device,
                non_blocking=(
                    device.type == "cuda"
                )
            )

            R_y = R_y.to(
                device,
                non_blocking=(
                    device.type == "cuda"
                )
            )

            A_y = A_y.to(
                device,
                non_blocking=(
                    device.type == "cuda"
                )
            )

            gamma_x = env_x[
                ...,
                0
            ]

            sigma_x = env_x[
                ...,
                1
            ]

            output = model(
                R_x,
                A_x,
                gamma_x,
                sigma_x
            )

            R_pred = output[
                "R_next"
            ]

            A_pred = output[
                "amplitude_next"
            ]

            R_loss = F.mse_loss(
                R_pred,
                R_y
            )

            A_loss = F.mse_loss(
                A_pred,
                A_y
            )

            loss = (
                R_loss
                +
                A_loss
            )

            n_batch = R_x.shape[0]

            val_loss_sum += (
                loss.item()
                *
                n_batch
            )

            val_R_sum += (
                R_loss.item()
                *
                n_batch
            )

            val_A_sum += (
                A_loss.item()
                *
                n_batch
            )

            val_count += n_batch

    val_loss = (
        val_loss_sum
        /
        val_count
    )

    val_R_loss = (
        val_R_sum
        /
        val_count
    )

    val_A_loss = (
        val_A_sum
        /
        val_count
    )

    scheduler.step(
        val_loss
    )

    current_lr = float(
        optimizer.param_groups[
            0
        ][
            "lr"
        ]
    )

    kappa_L = float(
        model
        .kappa_lindblad()
        .item()
    )

    kappa_N = float(
        model
        .kappa_neural()
        .item()
    )

    elapsed = (
        time.time()
        -
        start_time
    )

    improved = bool(
        val_loss
        <
        (
            best_val_loss
            -
            MIN_DELTA
        )
    )

    if improved:

        best_val_loss = (
            val_loss
        )

        best_epoch = (
            epoch
        )

        epochs_without_improvement = 0

        torch.save(

            {
                "model_state_dict":
                    model.state_dict(),

                "optimizer_state_dict":
                    optimizer.state_dict(),

                "scheduler_state_dict":
                    scheduler.state_dict(),

                "epoch":
                    int(epoch),

                "best_validation_loss":
                    float(
                        best_val_loss
                    ),

                "architecture":
                    {
                        "name":
                            "FinalRepairedLNO",

                        "dim":
                            6,

                        "width":
                            64,

                        "modes":
                            16,

                        "depth":
                            4,

                        "lindblad_channels":
                            4,
                    },

                "training":
                    {
                        "batch_size":
                            BATCH_SIZE,

                        "max_epochs":
                            MAX_EPOCHS,

                        "learning_rate":
                            1e-3,

                        "weight_decay":
                            1e-4,
                    },

                "amplitude_normalization":
                    {
                        "mean":
                            amplitude_mean,

                        "std":
                            amplitude_std,
                    },

                "physics":
                    {
                        "lindblad_in_forward_path":
                            True,

                        "physics_loss_penalty":
                            False,

                        "positive_lindblad_coupling":
                            True,

                        "positive_neural_coupling":
                            True,

                        "fresh_initialization":
                            True,
                    },

                "dataset":
                    "Dataset V3 Expanded",

                "prototype":
                    False,
            },

            BEST_CHECKPOINT
        )

    else:

        epochs_without_improvement += 1

    # --------------------------------------------------------
    # ALWAYS SAVE LAST CHECKPOINT
    # --------------------------------------------------------

    torch.save(

        {
            "model_state_dict":
                model.state_dict(),

            "optimizer_state_dict":
                optimizer.state_dict(),

            "scheduler_state_dict":
                scheduler.state_dict(),

            "epoch":
                int(epoch),

            "validation_loss":
                float(val_loss),

            "amplitude_normalization":
                {
                    "mean":
                        amplitude_mean,

                    "std":
                        amplitude_std,
                },
        },

        LAST_CHECKPOINT
    )

    # --------------------------------------------------------
    # HISTORY
    # --------------------------------------------------------

    history.append({

        "epoch":
            int(epoch),

        "train_loss":
            float(train_loss),

        "train_R_loss":
            float(train_R_loss),

        "train_amplitude_loss":
            float(train_A_loss),

        "val_loss":
            float(val_loss),

        "val_R_loss":
            float(val_R_loss),

        "val_amplitude_loss":
            float(val_A_loss),

        "learning_rate":
            float(current_lr),

        "kappa_lindblad":
            float(kappa_L),

        "kappa_neural":
            float(kappa_N),

        "time_seconds":
            float(elapsed),

        "improved":
            bool(improved),
    })

    # Save history EVERY epoch
    pd.DataFrame(
        history
    ).to_csv(
        HISTORY_PATH,
        index=False
    )

    # ========================================================
    # LOG
    # ========================================================

    print(
        f"\nEpoch {epoch:02d}/{MAX_EPOCHS}"
    )

    print(
        f"  Train total : {train_loss:.10e}"
    )

    print(
        f"  Train R     : {train_R_loss:.10e}"
    )

    print(
        f"  Train Amp   : {train_A_loss:.10e}"
    )

    print(
        f"  Val total   : {val_loss:.10e}"
    )

    print(
        f"  Val R       : {val_R_loss:.10e}"
    )

    print(
        f"  Val Amp     : {val_A_loss:.10e}"
    )

    print(
        f"  kappa_L     : {kappa_L:.8e}"
    )

    print(
        f"  kappa_N     : {kappa_N:.8e}"
    )

    print(
        f"  LR          : {current_lr:.3e}"
    )

    print(
        f"  Time        : {elapsed:.2f}s"
    )

    if improved:

        print(
            "  >>> NEW BEST LNO CHECKPOINT"
        )

    else:

        print(
            "  No improvement:"
            f" {epochs_without_improvement}/"
            f"{EARLY_STOPPING_PATIENCE}"
        )

    # --------------------------------------------------------
    # EARLY STOPPING
    # --------------------------------------------------------

    if (
        epochs_without_improvement
        >=
        EARLY_STOPPING_PATIENCE
    ):

        print(
            "\n[INFO] Early stopping triggered."
        )

        break


# ============================================================
# 20. TRAINING COMPLETE
# ============================================================

if not BEST_CHECKPOINT.is_file():

    raise RuntimeError(
        "Final LNO training ended without producing "
        "a best checkpoint."
    )

print(
    "\n" + "=" * 100
)

print(
    "TRAINING COMPLETE"
)

print(
    "=" * 100
)

print(
    "Best epoch:",
    best_epoch
)

print(
    "Best validation loss:",
    f"{best_val_loss:.12e}"
)

print(
    "Best checkpoint:",
    BEST_CHECKPOINT
)

print(
    "Last checkpoint:",
    LAST_CHECKPOINT
)

print(
    "History:",
    HISTORY_PATH
)


# ============================================================
# 21. RESTORE BEST CHECKPOINT
# ============================================================

best_checkpoint = torch.load(
    BEST_CHECKPOINT,
    map_location=device
)

model.load_state_dict(
    best_checkpoint[
        "model_state_dict"
    ]
)

model.eval()

print(
    "\n[PASS] Best LNO checkpoint restored."
)


# ============================================================
# 22. FINAL TEST FORWARD
# ============================================================

print(
    "\n" + "=" * 100
)

print(
    "FINAL LNO TEST EVALUATION"
)

print(
    "=" * 100
)

X_R_test_t = torch.from_numpy(
    X_R_test
).to(
    device
)

Y_R_test_t = torch.from_numpy(
    Y_R_test
).to(
    device
)

X_A_test_t = torch.from_numpy(
    X_A_test_n.astype(
        np.float32
    )
).to(
    device
)

Y_A_test_t = torch.from_numpy(
    Y_A_test_n.astype(
        np.float32
    )
).to(
    device
)

ENV_test_t = torch.from_numpy(
    ENV_test
).to(
    device
)

with torch.no_grad():

    gamma_test = ENV_test_t[
        ...,
        0
    ]

    sigma_test = ENV_test_t[
        ...,
        1
    ]

    output = model(
        X_R_test_t,
        X_A_test_t,
        gamma_test,
        sigma_test
    )

    R_pred = output[
        "R_next"
    ]

    A_pred_normalized = output[
        "amplitude_next"
    ]

    delta_L = output[
        "delta_R_lindblad"
    ]

    delta_N = output[
        "delta_R_neural"
    ]

    delta_total = output[
        "delta_R_total"
    ]


# ============================================================
# 23. RESTORE PHYSICAL AMPLITUDE
# ============================================================

A_pred = (
    A_pred_normalized
    *
    amplitude_std
    +
    amplitude_mean
)

A_target = (
    Y_A_test_t
    *
    amplitude_std
    +
    amplitude_mean
)


# ============================================================
# 24. METRICS
# ============================================================

R_error = (
    R_pred
    -
    Y_R_test_t
)

A_error = (
    A_pred
    -
    A_target
)

R_MSE = torch.mean(
    R_error ** 2
)

R_RMSE = torch.sqrt(
    R_MSE
    +
    1e-12
)

R_MAE = torch.mean(
    torch.abs(
        R_error
    )
)

R_relative_L2 = (
    torch.linalg.vector_norm(
        R_error
    )
    /
    (
        torch.linalg.vector_norm(
            Y_R_test_t
        )
        +
        1e-12
    )
)

A_MSE = torch.mean(
    A_error ** 2
)

A_RMSE = torch.sqrt(
    A_MSE
    +
    1e-12
)

A_MAE = torch.mean(
    torch.abs(
        A_error
    )
)

A_relative_L2 = (
    torch.linalg.vector_norm(
        A_error
    )
    /
    (
        torch.linalg.vector_norm(
            A_target
        )
        +
        1e-12
    )
)

print(
    "R MSE:",
    f"{R_MSE.item():.12e}"
)

print(
    "R RMSE:",
    f"{R_RMSE.item():.12e}"
)

print(
    "R MAE:",
    f"{R_MAE.item():.12e}"
)

print(
    "R Relative-L2:",
    f"{R_relative_L2.item():.12e}"
)

print(
    "\nAmplitude MSE:",
    f"{A_MSE.item():.12e}"
)

print(
    "Amplitude RMSE:",
    f"{A_RMSE.item():.12e}"
)

print(
    "Amplitude MAE:",
    f"{A_MAE.item():.12e}"
)

print(
    "Amplitude Relative-L2:",
    f"{A_relative_L2.item():.12e}"
)


# ============================================================
# 25. STRUCTURE
# ============================================================

trace = torch.diagonal(
    R_pred,
    dim1=-2,
    dim2=-1
).sum(
    dim=-1
)

trace_error = torch.abs(
    trace
    -
    1.0
)

mean_trace_error = float(
    trace_error.mean().item()
)

max_trace_error = float(
    trace_error.max().item()
)

symmetry_error = float(
    torch.max(
        torch.abs(
            R_pred
            -
            R_pred.transpose(
                -1,
                -2
            )
        )
    ).item()
)

eigvalues = torch.linalg.eigvalsh(
    R_pred
)

minimum_eigenvalue = float(
    eigvalues.min().item()
)

negative_eigenvalue_fraction = float(
    (
        eigvalues
        <
        0
    )
    .float()
    .mean()
    .item()
)

predictions_finite = bool(
    torch.isfinite(
        R_pred
    ).all().item()
    and
    torch.isfinite(
        A_pred
    ).all().item()
)

print(
    "\n" + "=" * 100
)

print(
    "LNO OUTPUT STRUCTURE"
)

print(
    "=" * 100
)

print(
    "Mean |trace - 1|:",
    f"{mean_trace_error:.12e}"
)

print(
    "Max |trace - 1|:",
    f"{max_trace_error:.12e}"
)

print(
    "Symmetry error:",
    f"{symmetry_error:.12e}"
)

print(
    "Minimum eigenvalue:",
    f"{minimum_eigenvalue:.12e}"
)

print(
    "Negative-eigenvalue fraction:",
    f"{negative_eigenvalue_fraction:.6f}"
)

print(
    "Predictions finite:",
    predictions_finite
)


# ============================================================
# 26. ENVIRONMENT RESPONSE
# ============================================================

probe_R = X_R_test_t[
    :1
].clone()

probe_A = torch.from_numpy(
    X_A_test_n[
        :1
    ].astype(
        np.float32
    )
).to(
    device
)

probe_sigma = ENV_test_t[
    :1,
    :,
    1
]

environment_rows = []

with torch.no_grad():

    for gamma_value in [

        0.0,
        0.01,
        0.05,
        0.15,
        0.35,
        0.50,

    ]:

        gamma_probe = torch.full_like(
            ENV_test_t[
                :1,
                :,
                0
            ],
            gamma_value
        )

        env_output = model(
            probe_R,
            probe_A,
            gamma_probe,
            probe_sigma
        )

        environment_rows.append({

            "gamma":
                float(
                    gamma_value
                ),

            "R_change":
                float(
                    torch.linalg.vector_norm(
                        env_output[
                            "R_next"
                        ]
                        -
                        probe_R
                    ).item()
                ),

            "amplitude_change":
                float(
                    torch.linalg.vector_norm(
                        env_output[
                            "amplitude_next"
                        ]
                        -
                        probe_A
                    ).item()
                ),

            "Lindblad_delta_norm":
                float(
                    torch.linalg.vector_norm(
                        env_output[
                            "delta_R_lindblad"
                        ]
                    ).item()
                ),

            "Neural_delta_norm":
                float(
                    torch.linalg.vector_norm(
                        env_output[
                            "delta_R_neural"
                        ]
                    ).item()
                ),
        })

environment_df = pd.DataFrame(
    environment_rows
)

print(
    "\n" + "=" * 100
)

print(
    "ENVIRONMENT COUPLING RESPONSE"
)

print(
    "=" * 100
)

display(
    environment_df.round(8)
)

environment_df.to_csv(
    ENVIRONMENT_PATH,
    index=False
)


# ============================================================
# 27. 40-STEP ROLLOUT
# ============================================================

R_roll = X_R_test_t[
    :1
].clone()

A_roll = torch.from_numpy(
    X_A_test_n[
        :1
    ].astype(
        np.float32
    )
).to(
    device
)

gamma_roll = ENV_test_t[
    :1,
    :,
    0
].clone()

sigma_roll = ENV_test_t[
    :1,
    :,
    1
].clone()

rollout_rows = []

with torch.no_grad():

    for step in range(
        1,
        41
    ):

        out = model(
            R_roll,
            A_roll,
            gamma_roll,
            sigma_roll
        )

        R_roll = out[
            "R_next"
        ]

        A_roll = out[
            "amplitude_next"
        ]

        tr = torch.diagonal(
            R_roll,
            dim1=-2,
            dim2=-1
        ).sum(
            dim=-1
        )

        eig = torch.linalg.eigvalsh(
            R_roll
        )

        finite_step = bool(
            torch.isfinite(
                R_roll
            ).all().item()
            and
            torch.isfinite(
                A_roll
            ).all().item()
        )

        rollout_rows.append({

            "step":
                int(step),

            "R_norm":
                float(
                    torch.linalg.vector_norm(
                        R_roll
                    ).item()
                ),

            "amplitude_norm":
                float(
                    torch.linalg.vector_norm(
                        A_roll
                    ).item()
                ),

            "trace_mean":
                float(
                    tr.mean().item()
                ),

            "min_eigenvalue":
                float(
                    eig.min().item()
                ),

            "finite":
                finite_step,
        })

rollout_df = pd.DataFrame(
    rollout_rows
)

rollout_min_eig = float(
    rollout_df[
        "min_eigenvalue"
    ].min()
)

rollout_max_trace_error = float(
    np.max(
        np.abs(
            rollout_df[
                "trace_mean"
            ].to_numpy()
            -
            1.0
        )
    )
)

rollout_finite = bool(
    rollout_df[
        "finite"
    ].all()
)

rollout_stable = bool(
    rollout_finite
    and
    rollout_max_trace_error < 1e-4
    and
    rollout_min_eig > -1e-6
)

print(
    "\n" + "=" * 100
)

print(
    "40-STEP ROLLOUT"
)

print(
    "=" * 100
)

display(
    rollout_df.iloc[
        [
            0,
            9,
            19,
            29,
            39
        ]
    ].round(8)
)

print(
    "Minimum rollout eigenvalue:",
    f"{rollout_min_eig:.12e}"
)

print(
    "Maximum rollout trace error:",
    f"{rollout_max_trace_error:.12e}"
)

print(
    "Rollout finite:",
    rollout_finite
)

print(
    "Rollout stable:",
    rollout_stable
)

rollout_df.to_csv(
    ROLLOUT_PATH,
    index=False
)


# ============================================================
# 28. DYNAMICAL COMPONENT MAGNITUDES
# ============================================================

target_delta_norm = float(
    torch.linalg.vector_norm(
        Y_R_test_t
        -
        X_R_test_t
    ).item()
)

lindblad_delta_norm = float(
    torch.linalg.vector_norm(
        delta_L
    ).item()
)

neural_delta_norm = float(
    torch.linalg.vector_norm(
        delta_N
    ).item()
)

combined_delta_norm = float(
    torch.linalg.vector_norm(
        delta_total
    ).item()
)

final_kappa_L = float(
    model
    .kappa_lindblad()
    .item()
)

final_kappa_N = float(
    model
    .kappa_neural()
    .item()
)

print(
    "\n" + "=" * 100
)

print(
    "LEARNED DYNAMICAL COMPONENTS"
)

print(
    "=" * 100
)

print(
    "Target ΔR norm:",
    f"{target_delta_norm:.12e}"
)

print(
    "Lindblad ΔR norm:",
    f"{lindblad_delta_norm:.12e}"
)

print(
    "Neural ΔR norm:",
    f"{neural_delta_norm:.12e}"
)

print(
    "Combined ΔR norm:",
    f"{combined_delta_norm:.12e}"
)

print(
    "Final kappa_L:",
    f"{final_kappa_L:.12e}"
)

print(
    "Final kappa_N:",
    f"{final_kappa_N:.12e}"
)


# ============================================================
# 29. REGIME-WISE TEST METRICS
# ============================================================

manifest_path = (
    ROOT
    / "results"
    / "step16_final_splits"
    / "final_transition_manifest.csv"
)

manifest = pd.read_csv(
    manifest_path
)

assert len(
    manifest
) == N_TOTAL

test_manifest = manifest.iloc[
    test_indices
].reset_index(
    drop=True
)

assert len(
    test_manifest
) == len(
    test_indices
)

R_error_np = (
    R_error
    .detach()
    .cpu()
    .numpy()
)

A_error_np = (
    A_error
    .detach()
    .cpu()
    .numpy()
)

A_target_np = (
    A_target
    .detach()
    .cpu()
    .numpy()
)

regime_rows = []

for regime in sorted(
    test_manifest[
        "regime"
    ].unique()
):

    mask = (
        test_manifest[
            "regime"
        ].to_numpy()
        ==
        regime
    )

    r_err = R_error_np[
        mask
    ]

    a_err = A_error_np[
        mask
    ]

    r_target = Y_R_test[
        mask
    ]

    a_target = A_target_np[
        mask
    ]

    r_rel = (
        np.linalg.norm(
            r_err
        )
        /
        (
            np.linalg.norm(
                r_target
            )
            +
            1e-12
        )
    )

    a_rel = (
        np.linalg.norm(
            a_err
        )
        /
        (
            np.linalg.norm(
                a_target
            )
            +
            1e-12
        )
    )

    regime_rows.append({

        "regime":
            regime,

        "transitions":
            int(
                mask.sum()
            ),

        "R_RMSE":
            float(
                np.sqrt(
                    np.mean(
                        r_err ** 2
                    )
                )
            ),

        "R_MAE":
            float(
                np.mean(
                    np.abs(
                        r_err
                    )
                )
            ),

        "R_relative_L2":
            float(
                r_rel
            ),

        "amplitude_RMSE":
            float(
                np.sqrt(
                    np.mean(
                        a_err ** 2
                    )
                )
            ),

        "amplitude_MAE":
            float(
                np.mean(
                    np.abs(
                        a_err
                    )
                )
            ),

        "amplitude_relative_L2":
            float(
                a_rel
            ),
    })

regime_df = pd.DataFrame(
    regime_rows
)

print(
    "\n" + "=" * 100
)

print(
    "REGIME-WISE FINAL LNO PERFORMANCE"
)

print(
    "=" * 100
)

display(
    regime_df.round(8)
)

regime_df.to_csv(
    REGIME_PATH,
    index=False
)


