# ============================================================

def calculate_metrics(
    prediction,
    target
):

    error = (
        prediction
        -
        target
    )

    mse = float(
        np.mean(
            error ** 2
        )
    )

    rmse = float(
        np.sqrt(
            mse
        )
    )

    mae = float(
        np.mean(
            np.abs(
                error
            )
        )
    )

    numerator = np.linalg.norm(
        error
    )

    denominator = (
        np.linalg.norm(
            target
        )
        +
        1e-12
    )

    relative_l2 = float(
        numerator
        /
        denominator
    )

    return {

        "MSE":
            mse,

        "RMSE":
            rmse,

        "MAE":
            mae,

        "Relative-L2":
            relative_l2,
    }


def percentage_change(
    new_value,
    old_value
):

    return float(
        (
            new_value
            -
            old_value
        )
        /
        (
            abs(
                old_value
            )
            +
            1e-12
        )
        *
        100.0
    )


