# ------------------------------------------------------------
# Basic checks
# ------------------------------------------------------------

assert "regime" in fno_regime.columns
assert "regime" in lno_regime.columns

assert set(
    fno_regime[
        "regime"
    ]
) == set(
    lno_regime[
        "regime"
    ]
)


# ------------------------------------------------------------
# Merge
# ------------------------------------------------------------

merged_regime = fno_regime.merge(
    lno_regime,
    on="regime",
    suffixes=(
        "_FNO",
        "_LNO"
    )
)


# ------------------------------------------------------------
# Transition counts
#
# Both files may contain "transitions".
# After merge they become:
#
#   transitions_FNO
#   transitions_LNO
#
# We verify they agree and create one clean column.
# ------------------------------------------------------------

if (
    "transitions_FNO" in merged_regime.columns
    and
    "transitions_LNO" in merged_regime.columns
):

    transition_difference = (
        merged_regime[
            "transitions_FNO"
        ].to_numpy()
        -
        merged_regime[
            "transitions_LNO"
        ].to_numpy()
    )

    assert np.all(
        transition_difference == 0
    )

    merged_regime[
        "transitions"
    ] = (
        merged_regime[
            "transitions_FNO"
        ]
        .astype(
            int
        )
    )

elif "transitions" in merged_regime.columns:

    merged_regime[
        "transitions"
    ] = (
        merged_regime[
            "transitions"
        ]
        .astype(
            int
        )
    )

else:

    raise KeyError(
        "No transition-count column found in merged regime table."
    )


# ------------------------------------------------------------
# R Relative-L2 change
#
# Positive = LNO worse
# Negative = LNO better
# ------------------------------------------------------------

merged_regime[
    "R_relative_L2_change_percent"
] = (

    (
        merged_regime[
            "R_relative_L2_LNO"
        ]
        -
        merged_regime[
            "R_relative_L2_FNO"
        ]
    )
    /
    (
        np.abs(
            merged_regime[
                "R_relative_L2_FNO"
            ]
        )
        +
        1e-12
    )
    *
    100.0
)


# ------------------------------------------------------------
# Amplitude Relative-L2 change
# ------------------------------------------------------------

merged_regime[
    "Amplitude_relative_L2_change_percent"
] = (

    (
        merged_regime[
            "amplitude_relative_L2_LNO"
        ]
        -
        merged_regime[
            "amplitude_relative_L2_FNO"
        ]
    )
    /
    (
        np.abs(
            merged_regime[
                "amplitude_relative_L2_FNO"
            ]
        )
        +
        1e-12
    )
    *
    100.0
)


# ------------------------------------------------------------
# R winner
# ------------------------------------------------------------

merged_regime[
    "R_winner"
] = np.where(

    merged_regime[
        "R_relative_L2_LNO"
    ]
    <
    merged_regime[
        "R_relative_L2_FNO"
    ],

    "LNO",

    "FNO"
)


# ------------------------------------------------------------
# Amplitude winner
# ------------------------------------------------------------

merged_regime[
    "Amplitude_winner"
] = np.where(

    merged_regime[
        "amplitude_relative_L2_LNO"
    ]
    <
    merged_regime[
        "amplitude_relative_L2_FNO"
    ],

    "LNO",

    "FNO"
)


# ------------------------------------------------------------
# Final clean regime table
# ------------------------------------------------------------

regime_output = merged_regime[
    [

        "regime",

        "transitions",

        "R_relative_L2_FNO",
        "R_relative_L2_LNO",
        "R_relative_L2_change_percent",

        "amplitude_relative_L2_FNO",
        "amplitude_relative_L2_LNO",
        "Amplitude_relative_L2_change_percent",

        "R_winner",
        "Amplitude_winner",
    ]
].copy()


