def save_square(
    fig,
    name
):

    png_path = (
        FIG_DIR
        / f"{name}.png"
    )

    svg_path = (
        FIG_DIR
        / f"{name}.svg"
    )

    single_pdf_path = (
        FIG_DIR
        / f"{name}.pdf"
    )

    fig.savefig(
        png_path,
        dpi=600,
        facecolor="white",
        edgecolor="none",
        bbox_inches="tight"
    )

    fig.savefig(
        svg_path,
        facecolor="white",
        edgecolor="none",
        bbox_inches="tight"
    )

    fig.savefig(
        single_pdf_path,
        facecolor="white",
        edgecolor="none",
        bbox_inches="tight"
    )

    pdf.savefig(
        fig,
        facecolor="white",
        edgecolor="none",
        bbox_inches="tight"
    )

    plt.show()

    plt.close(
        fig
    )

    print(
        f"[+] {name}"
    )


def scientific(
    value,
    digits=2
):

    return (
        f"{value:.{digits}e}"
    )


