# 3. FLEXIBLE FILE LOCATOR
# ============================================================
#
# Because two large NPZ files may have been manually uploaded
# outside the repository folder, search /content recursively.
#
# ============================================================

def locate_file(
    filename,
    preferred_paths=None,
    required=True
):

    if preferred_paths is None:
        preferred_paths = []

    # --------------------------------------------------------
    # 1. Preferred exact locations
    # --------------------------------------------------------

    for path in preferred_paths:

        path = Path(path)

        if path.is_file():

            return path


    # --------------------------------------------------------
    # 2. Search repository
    # --------------------------------------------------------

    repo_matches = list(
        ROOT.rglob(
            filename
        )
    )

    if repo_matches:

        return repo_matches[0]


    # --------------------------------------------------------
    # 3. Search /content
    # --------------------------------------------------------

    content_root = Path(
        "/content"
    )

    matches = []

    for path in content_root.rglob(
        filename
    ):

        if path.is_file():

            matches.append(
                path
            )

    if matches:

        # Prefer newest file if several uploads exist.
        matches.sort(
            key=lambda p: p.stat().st_mtime,
            reverse=True
        )

        return matches[0]


    if required:

        raise FileNotFoundError(
            f"Could not locate required file:\n{filename}"
        )

    return None


