with torch.no_grad():

    for regime_index, regime_name in enumerate(
        regimes.keys()
    ):

        start = (
            regime_index
            *
            REP_PER_REGIME
        )

        end = (
            start
            +
            REP_PER_REGIME
        )

        R_init = R0[
            start:end
        ].clone()

        A_init = A0[
            start:end
        ].clone()

        gamma_regime = gamma0[
            start:end
        ]

        sigma_regime = sigma0[
            start:end
        ]


        print(
            "\n" + "-" * 100
        )

        print(
            "REGIME:",
            regime_name
        )

        print(
            "-" * 100
        )


        # --------------------------------------------------------
        # FNO
        # --------------------------------------------------------

        R_fno = R_init.clone()
        A_fno = A_init.clone()

        fno_failed = False

        for step in range(
            ROLLOUT_STEPS
        ):

            if (
                not torch.isfinite(R_fno).all()
                or
                not torch.isfinite(A_fno).all()
            ):

                fno_failed = True

                break

            result_fno = fno_model(
                R_fno,
                A_fno,
                gamma_regime,
                sigma_regime
            )

            R_next = result_fno[
                "R_next"
            ]

            A_next = result_fno[
                "amplitude_next"
            ]

            if (
                not torch.isfinite(R_next).all()
                or
                not torch.isfinite(A_next).all()
            ):

                fno_failed = True

                break

            R_fno = R_next
            A_fno = A_next

            metrics = structural_metrics(
                R_fno
            )

            metrics[
                "amplitude_norm"
            ] = float(
                torch.linalg.vector_norm(
                    A_fno
                ).item()
            )

            detail_rows.append(
                {
                    "regime": regime_name,
                    "model": "FNO",
                    "step": step + 1,
                    **metrics,
                }
            )


        # --------------------------------------------------------
        # LNO
        # --------------------------------------------------------

        R_lno = R_init.clone()
        A_lno = A_init.clone()

        lno_failed = False

        for step in range(
            ROLLOUT_STEPS
        ):

            if (
                not torch.isfinite(R_lno).all()
                or
                not torch.isfinite(A_lno).all()
            ):

                lno_failed = True

                break

            try:

                result_lno = lno_model(
                    R_lno,
                    A_lno,
                    gamma_regime,
                    sigma_regime
                )

            except RuntimeError:

                lno_failed = True

                break

            R_next = result_lno[
                "R_next"
            ]

            A_next = result_lno[
                "amplitude_next"
            ]

            if (
                not torch.isfinite(R_next).all()
                or
                not torch.isfinite(A_next).all()
            ):

                lno_failed = True

                break

            R_lno = R_next
            A_lno = A_next

            metrics = structural_metrics(
                R_lno
            )

            metrics[
                "amplitude_norm"
            ] = float(
                torch.linalg.vector_norm(
                    A_lno
                ).item()
            )

            detail_rows.append(
                {
                    "regime": regime_name,
                    "model": "LNO",
                    "step": step + 1,
                    **metrics,
                }
            )


        print(
            "FNO:",
            "FAILED" if fno_failed else "100/100"
        )

        print(
            "LNO:",
            "FAILED" if lno_failed else "100/100"
        )


