# ============================================================
# 13. METRIC FUNCTION
# ============================================================

def calculate_metrics(
    prediction,
    target
):

    error = (
        prediction
        -
        target
    )

    mse = float(
        np.mean(
            error ** 2
        )
    )

    rmse = float(
        np.sqrt(
            mse
        )
    )

    mae = float(
        np.mean(
            np.abs(
                error
            )
        )
    )

    relative_l2 = float(
        np.linalg.norm(
            error
        )
        /
        (
            np.linalg.norm(
                target
            )
            +
            1e-12
        )
    )

    return {
        "MSE": mse,
        "RMSE": rmse,
        "MAE": mae,
        "Relative-L2": relative_l2,
    }


