fno_R_error = (
    fno_R_pred
    -
    fno_R_target
)

lno_R_error = (
    lno_R_pred
    -
    lno_R_target
)

fno_A_error = (
    fno_A_pred
    -
    fno_A_target
)

lno_A_error = (
    lno_A_pred
    -
    lno_A_target
)


R_axes = tuple(
    range(
        1,
        fno_R_error.ndim
    )
)

fno_R_transition_rmse = np.sqrt(
    np.mean(
        fno_R_error ** 2,
        axis=R_axes
    )
)

lno_R_transition_rmse = np.sqrt(
    np.mean(
        lno_R_error ** 2,
        axis=R_axes
    )
)

fno_A_transition_rmse = np.sqrt(
    np.mean(
        fno_A_error ** 2,
        axis=1
    )
)

lno_A_transition_rmse = np.sqrt(
    np.mean(
        lno_A_error ** 2,
        axis=1
    )
)


