# ======================================================================================
# 10. METRICS
# ======================================================================================

def metrics(pred, target):

    mse = F.mse_loss(
        pred,
        target
    ).item()

    rmse = math.sqrt(mse)

    mae = torch.mean(
        torch.abs(
            pred - target
        )
    ).item()

    rel = (
        torch.linalg.vector_norm(
            pred - target
        )
        /
        torch.linalg.vector_norm(
            target
        ).clamp_min(1e-8)
    ).item()

    return {
        "MSE": mse,
        "RMSE": rmse,
        "MAE": mae,
        "Relative_L2": rel
    }


c_r = metrics(
    C_R_pred,
    C_R_true
)

c_a = metrics(
    C_A_pred,
    C_A_true
)


# ======================================================================================
# 11. STRUCTURAL METRICS
# ======================================================================================

def structural_metrics(R):

    trace = torch.diagonal(
        R,
        dim1=-2,
        dim2=-1
    ).sum(
        dim=-1
    )

    trace_error = torch.abs(
        trace - 1.0
    )

    eig = torch.linalg.eigvalsh(
        R
    )

    return {
        "Mean_trace_error":
            float(trace_error.mean().item()),

        "Max_trace_error":
            float(trace_error.max().item()),

        "Minimum_eigenvalue":
            float(eig.min().item()),

        "Negative_eigenvalue_fraction":
            float(
                (eig < -1e-6)
                .float()
                .mean()
                .item()
            )
    }


