def find_file(filename):

    direct = CONTENT_ROOT / filename

    if direct.is_file():
        return direct

    repo_matches = list(
        ROOT.rglob(filename)
    )

    if repo_matches:
        return repo_matches[0]

    content_matches = [
        p for p in CONTENT_ROOT.rglob(filename)
        if p.is_file()
    ]

    if content_matches:
        return content_matches[0]

    return None


