# ======================================================================================
# 6. SPECTRAL CONVOLUTION
# ======================================================================================

class SpectralConv1D(nn.Module):

    def __init__(
        self,
        in_channels,
        out_channels,
        modes
    ):

        super().__init__()

        self.in_channels = in_channels
        self.out_channels = out_channels
        self.modes = modes

        scale = (
            1.0 /
            math.sqrt(
                in_channels *
                out_channels
            )
        )

        self.weight_real = nn.Parameter(
            scale *
            torch.randn(
                in_channels,
                out_channels,
                modes
            )
        )

        self.weight_imag = nn.Parameter(
            scale *
            torch.randn(
                in_channels,
                out_channels,
                modes
            )
        )

    def forward(self, x):

        B, C, NX = x.shape

        x_ft = torch.fft.rfft(
            x,
            dim=-1
        )

        n_modes = min(
            self.modes,
            x_ft.shape[-1]
        )

        out_ft = torch.zeros(
            B,
            self.out_channels,
            x_ft.shape[-1],
            dtype=torch.complex64,
            device=x.device
        )

        weight = torch.complex(
            self.weight_real[
                ...,
                :n_modes
            ],
            self.weight_imag[
                ...,
                :n_modes
            ]
        )

        out_ft[
            ...,
            :n_modes
        ] = torch.einsum(
            "bim,iom->bom",
            x_ft[
                ...,
                :n_modes
            ],
            weight
        )

        return torch.fft.irfft(
            out_ft,
            n=NX,
            dim=-1
        )


# ======================================================================================
# 7. LINDBLAD KERNEL
# ======================================================================================

class LindbladKernel(nn.Module):

    def __init__(
        self,
        dim=6,
        channels=4
    ):

        super().__init__()

        self.jump_operators = nn.Parameter(
            0.02 *
            torch.randn(
                channels,
                dim,
                dim
            )
        )

    def forward(self, R):

        total = torch.zeros_like(
            R
        )

        for k in range(4):

            L = self.jump_operators[k]

            LT = L.transpose(
                -1,
                -2
            )

            A = (
                LT @ L
            )

            jump_term = (
                L @ R @ LT
            )

            anti_term = (
                A @ R +
                R @ A
            )

            total = (
                total
                +
                jump_term
                -
                0.5 * anti_term
            )

        return total


# ======================================================================================
# 8. FINAL REPAIRED LNO
# ======================================================================================

class FinalRepairedLNO(nn.Module):

    def __init__(
        self,
        dim=6,
        width=64,
        modes=16,
        depth=4,
        lindblad_channels=4
    ):

        super().__init__()

        self.dim = dim

        self.input_projection = nn.Conv1d(
            dim * dim + 3,
            width,
            kernel_size=1
        )

        self.spectral_layers = nn.ModuleList([
            SpectralConv1D(
                width,
                width,
                modes
            )
            for _ in range(depth)
        ])

        self.pointwise_layers = nn.ModuleList([
            nn.Conv1d(
                width,
                width,
                kernel_size=1
            )
            for _ in range(depth)
        ])

        self.R_head = nn.Conv1d(
            width,
            dim * dim,
            kernel_size=1
        )

        self.A_head = nn.Conv1d(
            width,
            1,
            kernel_size=1
        )

        self.lindblad = LindbladKernel(
            dim=dim,
            channels=lindblad_channels
        )

        self.raw_kappa_lindblad = nn.Parameter(
            torch.tensor(-0.5)
        )

        self.raw_kappa_neural = nn.Parameter(
            torch.tensor(0.5)
        )


    def project_R(self, R):

        original_dtype = R.dtype

        M = R.double()

        M = 0.5 * (
            M +
            M.transpose(-1, -2)
        )

        eigvals, eigvecs = torch.linalg.eigh(
            M
        )

        eigvals = torch.clamp(
            eigvals,
            min=1e-8
        )

        M_psd = (
            eigvecs *
            eigvals.unsqueeze(-2)
        ) @ eigvecs.transpose(
            -1,
            -2
        )

        trace = torch.diagonal(
            M_psd,
            dim1=-2,
            dim2=-1
        ).sum(
            dim=-1
        )

        trace = torch.clamp(
            trace,
            min=1e-12
        )

        M_psd = (
            M_psd /
            trace.unsqueeze(-1).unsqueeze(-1)
        )

        M_psd = 0.5 * (
            M_psd +
            M_psd.transpose(-1, -2)
        )

        return M_psd.to(
            original_dtype
        )


    def forward(
        self,
        R,
        amplitude,
        gamma,
        sigma
    ):

        B, NX, D, D2 = R.shape

        assert D == 6
        assert D2 == 6

        R_flat = R.reshape(
            B,
            NX,
            D * D
        )

        env = torch.stack(
            [
                amplitude,
                gamma,
                sigma
            ],
            dim=-1
        )

        x = torch.cat(
            [
                R_flat,
                env
            ],
            dim=-1
        ).permute(
            0,
            2,
            1
        )

        x = self.input_projection(
            x
        )

        for k in range(
            len(
                self.spectral_layers
            )
        ):

            x = (
                self.spectral_layers[k](x)
                +
                self.pointwise_layers[k](x)
            )

            if k < len(
                self.spectral_layers
            ) - 1:

                x = F.gelu(
                    x
                )

        G_N = torch.tanh(
            self.R_head(x)
            .permute(
                0,
                2,
                1
            )
            .reshape(
                B,
                NX,
                D,
                D
            )
        )

        G_L = self.lindblad(
            R
        )

        kappa_L = F.softplus(
            self.raw_kappa_lindblad
        )

        kappa_N = F.softplus(
            self.raw_kappa_neural
        )

        delta_R_lindblad = (
            kappa_L
            *
            gamma[..., None, None]
            *
            G_L
        )

        delta_R_neural = (
            kappa_N
            *
            G_N
        )

        delta_total = (
            delta_R_lindblad
            +
            delta_R_neural
        )

        R_next = self.project_R(
            R + delta_total
        )

        # IMPORTANT:
        # Same direct normalized amplitude head used by Step 26.
        A_next = self.A_head(
            x
        ).squeeze(
            1
        )

        return {
            "R_next":
                R_next,

            "amplitude_next":
                A_next
        }


