# ======================================================================================
# 10. STRUCTURAL METRICS
# ======================================================================================

def structural_metrics(
    R,
    A
):

    trace = torch.diagonal(
        R,
        dim1=-2,
        dim2=-1
    ).sum(
        dim=-1
    )

    trace_error = torch.abs(
        trace - 1.0
    )

    eig = torch.linalg.eigvalsh(
        R
    )

    return {

        "R_norm":
            float(
                torch.linalg
                .vector_norm(R)
                .item()
            ),

        "amplitude_norm":
            float(
                torch.linalg
                .vector_norm(A)
                .item()
            ),

        "mean_trace_error":
            float(
                trace_error.mean()
                .item()
            ),

        "max_trace_error":
            float(
                trace_error.max()
                .item()
            ),

        "minimum_eigenvalue":
            float(
                eig.min()
                .item()
            ),

        "negative_eigenvalue_fraction":
            float(
                (
                    eig < -1e-6
                )
                .float()
                .mean()
                .item()
            ),

        "finite":
            bool(
                torch.isfinite(
                    R
                ).all().item()
                and
                torch.isfinite(
                    A
                ).all().item()
            )
    }


