def cleanup():
    """
    Aggressive matplotlib / Python memory cleanup.
    """
    plt.close("all")
    gc.collect()


def style_axes(ax):
    """
    Clean publication axes.
    """
    ax.grid(
        True,
        alpha=0.20,
        linewidth=0.55
    )

    for spine in ax.spines.values():
        spine.set_linewidth(0.75)


def save_layout_variants(
    plot_function,
    basename
):
    """
    Generate square / two-column / wide versions.
    """

    variants = {

        "square":
            (
                SQUARE_DIR,
                (3.45, 3.45)
            ),

        "two_column":
            (
                TWO_COLUMN_DIR,
                (7.10, 3.55)
            ),

        "wide":
            (
                WIDE_DIR,
                (9.20, 4.20)
            ),
    }

    for variant_name, (
        target_dir,
        figsize
    ) in variants.items():

        fig = plot_function(figsize)

        fig.savefig(
            target_dir
            /
            f"{basename}_{variant_name}.png",
            dpi=600,
            bbox_inches="tight",
            facecolor="white"
        )

        fig.savefig(
            target_dir
            /
            f"{basename}_{variant_name}.pdf",
            bbox_inches="tight",
            facecolor="white"
        )

        fig.savefig(
            target_dir
            /
            f"{basename}_{variant_name}.svg",
            bbox_inches="tight",
            facecolor="white"
        )

        plt.close(fig)
        cleanup()


