# ======================================================================================
# 11. FIGURE 01 — OVERALL ACCURACY
# ======================================================================================

def fig01_overall(figsize):

    fig, ax = plt.subplots(
        figsize=figsize
    )

    x = np.arange(
        len(MODEL_ORDER)
    )

    width = 0.34

    r_values = [
        float(
            overall_df.loc[
                overall_df["model"] == model,
                "R_Relative_L2"
            ].iloc[0]
        )
        for model in MODEL_ORDER
    ]

    a_values = [
        float(
            overall_df.loc[
                overall_df["model"] == model,
                "Amplitude_Relative_L2"
            ].iloc[0]
        )
        for model in MODEL_ORDER
    ]

    ax.bar(
        x - width / 2,
        r_values,
        width,
        color=COLORS["FNO"],
        label="R Relative-L2",
        edgecolor="white",
        linewidth=0.7
    )

    ax.bar(
        x + width / 2,
        a_values,
        width,
        color=COLORS["C_LNO"],
        label="Amplitude Relative-L2",
        edgecolor="white",
        linewidth=0.7
    )

    ax.set_xticks(
        x
    )

    ax.set_xticklabels(
        [
            MODEL_LABELS[m]
            for m in MODEL_ORDER
        ]
    )

    ax.set_ylabel(
        "Relative-L2 error"
    )

    ax.set_title(
        "Overall One-Step Reconstruction Accuracy",
        fontweight="bold"
    )

    ax.legend(
        frameon=False
    )

    style_axes(ax)

    for i, v in enumerate(
        r_values
    ):

        ax.text(
            i - width / 2,
            v + 0.006,
            f"{v:.4f}",
            ha="center",
            va="bottom",
            fontsize=7.5
        )

    for i, v in enumerate(
        a_values
    ):

        ax.text(
            i + width / 2,
            v + 0.006,
            f"{v:.4f}",
            ha="center",
            va="bottom",
            fontsize=7.5
        )

    fig.subplots_adjust(
        left=0.16,
        right=0.97,
        bottom=0.18,
        top=0.88
    )

    return fig


