# 14. FIGURE 04 — 100-STEP TRACE STABILITY
# ======================================================================================

def fig04_trace_stability(figsize):

    fig, ax = plt.subplots(
        figsize=figsize
    )

    for regime in stability_df["regime"]:

        df = rollout_df[
            rollout_df["regime"] == regime
        ]

        curve = (
            df.groupby("step")[
                "max_trace_error"
            ]
            .mean()
        )

        curve_values = np.maximum(
            curve.to_numpy(dtype=float),
            1e-14
        )

        ax.plot(
            curve.index,
            curve_values,
            linewidth=1.65,
            color=COLORS.get(
                regime,
                COLORS["gray"]
            ),
            label=regime
        )

    ax.set_yscale(
        "log"
    )

    ax.set_xlabel(
        "Rollout step"
    )

    ax.set_ylabel(
        "Maximum trace error"
    )

    ax.set_title(
        "C-LNO Long-Horizon Trace Preservation",
        fontweight="bold"
    )

    ax.legend(
        frameon=False,
        fontsize=7.5
    )

    style_axes(ax)

    fig.subplots_adjust(
        left=0.15,
        right=0.98,
        bottom=0.16,
        top=0.88
    )

    return fig


