def add_box(
    x,
    y,
    width,
    height,
    title,
    subtitle,
    facecolor,
    title_size=10.5,
    subtitle_size=8.2
):

    patch = FancyBboxPatch(
        (
            x,
            y
        ),
        width,
        height,
        boxstyle=(
            "round,pad=0.06,"
            "rounding_size=0.10"
        ),
        linewidth=1.05,
        edgecolor=COLORS["dark"],
        facecolor=facecolor
    )

    ax.add_patch(
        patch
    )

    ax.text(
        x + width / 2,
        y + height * 0.63,
        title,
        ha="center",
        va="center",
        fontsize=title_size,
        fontweight="bold"
    )

    ax.text(
        x + width / 2,
        y + height * 0.31,
        subtitle,
        ha="center",
        va="center",
        fontsize=subtitle_size,
        color=COLORS["gray"]
    )


def add_arrow(
    start,
    end,
    color=None,
    linewidth=1.45,
    rad=0.0
):

    if color is None:
        color = COLORS["dark"]

    arrow = FancyArrowPatch(
        start,
        end,
        arrowstyle="-|>",
        mutation_scale=15,
        linewidth=linewidth,
        color=color,
        connectionstyle=(
            f"arc3,rad={rad}"
        )
    )

    ax.add_patch(
        arrow
    )


