def interpolate_points(
    points,
    per_segment=10
):

    pieces = []

    for i in range(
        len(points) - 1
    ):

        a = points[i]
        b = points[i + 1]

        for t in np.linspace(
            0,
            1,
            per_segment,
            endpoint=False
        ):

            pieces.append(
                (1 - t) * a
                +
                t * b
            )

    pieces.append(
        points[-1]
    )

    return np.asarray(
        pieces
    )


architecture_path = interpolate_points(
    workflow_points,
    per_segment=10
)

