audit_results = []

errors = []

warnings = []


def record(
    check,
    passed,
    detail=""
):
    """
    Record a single audit result.
    """

    status = "PASS" if passed else "FAIL"

    audit_results.append({
        "check": check,
        "status": status,
        "detail": str(detail)
    })

    if passed:
        print(
            f"[PASS] {check}"
            + (
                f" — {detail}"
                if detail
                else ""
            )
        )
    else:
        print(
            f"[FAIL] {check}"
            + (
                f" — {detail}"
                if detail
                else ""
            )
        )
        errors.append(
            f"{check}: {detail}"
        )


def record_warning(
    check,
    detail=""
):
    """
    Record a non-fatal warning.
    """

    warnings.append(
        f"{check}: {detail}"
    )

    print(
        f"[WARN] {check}"
        + (
            f" — {detail}"
            if detail
            else ""
        )
    )


