def audit_gif(
    name,
    path
):

    record(
        f"{name} exists",
        path.is_file(),
        path
    )

    if not path.is_file():
        return None

    try:

        with Image.open(path) as img:

            frame_count = int(
                getattr(
                    img,
                    "n_frames",
                    1
                )
            )

            width, height = img.size

            duration = img.info.get(
                "duration",
                None
            )

        record(
            f"{name} readable",
            True,
            f"{width}x{height}"
        )

        record(
            f"{name} contains multiple frames",
            frame_count >= 2,
            f"{frame_count} frames"
        )

        if duration is None:

            record_warning(
                f"{name} duration metadata",
                "No explicit duration metadata found."
            )

        else:

            record(
                f"{name} frame duration available",
                duration > 0,
                f"{duration} ms"
            )

        return {
            "frames": frame_count,
            "width": width,
            "height": height,
            "duration_ms": duration,
        }

    except Exception as exc:

        record(
            f"{name} readable",
            False,
            repr(exc)
        )

        return None


