def zip_contains(
    relative_path
):

    # ZIP entries use POSIX separators.
    relative_path = str(
        relative_path
    ).replace(
        os.sep,
        "/"
    )

    expected = (
        OUT.name
        +
        "/"
        +
        relative_path
    )

    return expected in zip_names


