def inspect_gif(
    label,
    path
):

    record(
        f"{label} exists",
        path.is_file(),
        path
    )

    if not path.is_file():

        return None

    try:

        with Image.open(path) as img:

            frames = int(
                getattr(
                    img,
                    "n_frames",
                    1
                )
            )

            width, height = img.size

            duration = img.info.get(
                "duration",
                None
            )

        record(
            f"{label} readable",
            True,
            f"{width}x{height}"
        )

        record(
            f"{label} multiple frames",
            frames >= 2,
            frames
        )

        if duration is None:

            warning(
                f"{label} duration metadata",
                "Not present."
            )

        else:

            record(
                f"{label} duration metadata",
                duration > 0,
                f"{duration} ms"
            )

        return {
            "frames": frames,
            "width": width,
            "height": height,
            "duration_ms": duration,
            "size_bytes": path.stat().st_size,
        }

    except Exception as exc:

        record(
            f"{label} readable",
            False,
            repr(exc)
        )

        return None


arch_gif_info = inspect_gif(
    "Architecture GIF",
    ARCH_GIF
)

